#[derive(Debug, Deserialize, Serialize)]
struct BridgeDaemonRequest {
    #[serde(default)]
    id: u64,
    #[serde(default)]
    command: String,
    #[serde(default, alias = "requestArgs")]
    args: Vec<String>,
    #[serde(default)]
    place: Option<String>,
}

static PLACE_FILTER: Mutex<Option<String>> = Mutex::new(None);

fn set_place_filter(value: Option<String>) {
    let mut guard = PLACE_FILTER
        .lock()
        .unwrap_or_else(|error| error.into_inner());
    *guard = value.filter(|text| !text.trim().is_empty());
}

fn place_filter() -> Option<String> {
    PLACE_FILTER
        .lock()
        .unwrap_or_else(|error| error.into_inner())
        .clone()
}

fn place_matches(info: &BridgeInfoPayload, selector: &str) -> bool {
    let trimmed = selector.trim();
    if trimmed.is_empty() {
        return true;
    }
    if let Ok(id) = trimmed.parse::<i64>()
        && (info.place_id == Some(id) || info.game_id == Some(id))
    {
        return true;
    }
    let name = info.place_name.to_ascii_lowercase();
    let wanted = trimmed.to_ascii_lowercase();
    !name.is_empty() && (name == wanted || name.contains(&wanted))
}

fn validate_daemon_request(request: &BridgeDaemonRequest) -> Result<()> {
    if request.command.len() > 96 {
        bail!("Daemon command exceeds 96 bytes");
    }
    if request.args.len() > MAX_DAEMON_ARGS {
        bail!(
            "Daemon request has too many arguments ({}; maximum is {MAX_DAEMON_ARGS})",
            request.args.len()
        );
    }
    let mut total_bytes = request.command.len();
    for argument in &request.args {
        if argument.len() > MAX_DAEMON_ARG_BYTES {
            bail!(
                "Daemon argument exceeds {MAX_DAEMON_ARG_BYTES} bytes; use a file-backed input instead"
            );
        }
        total_bytes = total_bytes.saturating_add(argument.len());
        if total_bytes > MAX_DAEMON_LINE_BYTES {
            bail!("Daemon request arguments exceed {MAX_DAEMON_LINE_BYTES} bytes");
        }
    }
    Ok(())
}

