#[derive(Debug, Default)]
struct EditorPropertyFilter {
    settings_ids: HashSet<String>,
    property_names: HashSet<String>,
}

impl EditorPropertyFilter {
    fn from_args(args: &PushEditorChangesArgs) -> Result<Self> {
        Ok(Self {
            settings_ids: expand_editor_target_settings_ids(args)?,
            property_names: args
                .target_properties
                .iter()
                .map(|value| value.trim().to_ascii_lowercase())
                .filter(|value| !value.is_empty())
                .collect(),
        })
    }

    fn is_active(&self) -> bool {
        !self.settings_ids.is_empty() || !self.property_names.is_empty()
    }

    fn has_settings_targets(&self) -> bool {
        !self.settings_ids.is_empty()
    }

    fn includes_instance(&self, settings_id: &str) -> bool {
        self.settings_ids.is_empty() || self.settings_ids.contains(settings_id)
    }

    fn includes_property(&self, property_name: &str) -> bool {
        self.property_names.is_empty()
            || self
                .property_names
                .contains(&property_name.to_ascii_lowercase())
    }

    fn explicitly_targets_property(&self, property_name: &str) -> bool {
        !self.property_names.is_empty()
            && self
                .property_names
                .contains(&property_name.to_ascii_lowercase())
    }
}

fn expand_editor_target_settings_ids(args: &PushEditorChangesArgs) -> Result<HashSet<String>> {
    let mut ids = HashSet::new();
    for value in &args.target_settings_ids {
        let trimmed = value.trim();
        if !trimmed.is_empty() {
            ids.insert(trimmed.to_string());
        }
    }
    for list_path in &args.target_settings_id_files {
        let raw = fs::read_to_string(list_path).with_context(|| {
            format!(
                "Failed to read target settings id file {}",
                list_path.display()
            )
        })?;
        for line in raw.lines() {
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }
            ids.insert(trimmed.to_string());
        }
    }
    Ok(ids)
}

