struct BridgeChannel {
    port: u16,
    sockets: Mutex<HashMap<String, BridgeSocket>>,
}

struct BridgeServer {
    channels: Vec<Arc<BridgeChannel>>,
    alive: Arc<AtomicBool>,
    next_id: std::sync::atomic::AtomicU64,
    preferred_index: std::sync::atomic::AtomicUsize,

    request_gate: Mutex<()>,

    runtime_pins: Mutex<HashMap<RuntimePinKey, RuntimePin>>,
}

#[derive(Debug, Clone, Copy, Default)]
struct BridgeListenMetrics {
    bind_ms: f64,
    wait_for_channels_ms: f64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum BridgeTarget {
    Edit,
    Main,
    Client,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct RuntimePinKey {
    target: BridgeTarget,
    player: Option<String>,
}

#[derive(Debug, Clone)]
struct RuntimePin {
    runtime_id: Option<String>,
    socket_keys_by_port: HashMap<u16, String>,
}

struct RuntimePinCandidate {
    runtime_id: String,
    socket_keys_by_port: HashMap<u16, String>,
    role_rank: usize,
    last_focused_at: Instant,
}

fn normalize_bridge_role(role: &str) -> &'static str {
    match role.trim().to_ascii_lowercase().as_str() {
        "" | "edit" | "studio" | "plugin" => BRIDGE_ROLE_EDIT,
        "server" | "play" | "play-server" => BRIDGE_ROLE_PLAY_SERVER,
        "client" | "local" | "play-client" => BRIDGE_ROLE_PLAY_CLIENT,
        _ => BRIDGE_ROLE_UNKNOWN,
    }
}

impl BridgeServer {
    fn acquire_request_gate(&self, timeout: Duration) -> Result<MutexGuard<'_, ()>> {
        let deadline = Instant::now() + timeout;
        loop {
            match self.request_gate.try_lock() {
                Ok(guard) => return Ok(guard),
                Err(TryLockError::Poisoned(poisoned)) => return Ok(poisoned.into_inner()),
                Err(TryLockError::WouldBlock) if Instant::now() >= deadline => {
                    bail!(
                        "Renium daemon is busy with another bridge request; retry after it completes"
                    );
                }
                Err(TryLockError::WouldBlock) => thread::sleep(Duration::from_millis(5)),
            }
        }
    }

    fn listen(host: &str, ports: &[u16], wait_seconds: f64) -> Result<(Self, BridgeListenMetrics)> {
        Self::listen_with_initial_wait(host, ports, wait_seconds, true)
    }

    fn listen_with_initial_wait(
        host: &str,
        ports: &[u16],
        wait_seconds: f64,
        wait_for_initial_channels: bool,
    ) -> Result<(Self, BridgeListenMetrics)> {
        let bind_host = normalize_loopback_bridge_host(host)?;
        let bind_started = Instant::now();
        let alive = Arc::new(AtomicBool::new(true));
        let mut channels: Vec<Arc<BridgeChannel>> = Vec::with_capacity(ports.len());
        let request_session_id = format!(
            "{:x}-{:x}",
            std::process::id(),
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .map(|duration| duration.as_nanos())
                .unwrap_or(0)
        );

        for port in ports {
            let listener = TcpListener::bind((bind_host.as_str(), *port))
                .with_context(|| format!("Failed to bind bridge server on {bind_host}:{port}"))?;
            listener.set_nonblocking(true).with_context(|| {
                format!("Failed to set nonblocking listener {bind_host}:{port}")
            })?;
            println!("[renium] bridge listening on {bind_host}:{port}");

            let channel = Arc::new(BridgeChannel {
                port: *port,
                sockets: Mutex::new(HashMap::new()),
            });
            Self::spawn_accept_loop(
                bind_host.clone(),
                *port,
                listener,
                channel.clone(),
                alive.clone(),
                request_session_id.clone(),
            );
            channels.push(channel);
        }

        #[cfg(windows)]
        Self::spawn_focus_watcher(channels.clone(), alive.clone());

        let bind_ms = elapsed_ms(bind_started);
        let wait_started = Instant::now();
        let server = Self {
            channels,
            alive,
            next_id: std::sync::atomic::AtomicU64::new(21335),
            preferred_index: std::sync::atomic::AtomicUsize::new(0),
            request_gate: Mutex::new(()),
            runtime_pins: Mutex::new(HashMap::new()),
        };

        let required_channels = server.channels.len();
        if required_channels == 0 {
            bail!("No bridge ports configured");
        }

        if wait_for_initial_channels {
            let deadline = Instant::now() + Duration::from_secs_f64(wait_seconds.max(1.0));
            let mut last_ready_channels = 0usize;
            while Instant::now() < deadline {
                let ready_channels = server.channel_count();
                if ready_channels != last_ready_channels {
                    last_ready_channels = ready_channels;
                    println!(
                        "[renium] bridge ready channels: {}/{}",
                        ready_channels, required_channels
                    );
                }
                if ready_channels >= required_channels {
                    break;
                }
                thread::sleep(Duration::from_millis(2));
            }

            let ready_channels = server.channel_count();
            if ready_channels < required_channels {
                let missing_ports = server.missing_ports();
                bail!(
                    "Only {}/{} plugin bridge channels connected within {:.1}s; all {} are required for stable full-speed export. Missing ports: {:?}",
                    ready_channels,
                    required_channels,
                    wait_seconds.max(1.0),
                    required_channels,
                    missing_ports
                );
            }

            println!(
                "[renium] bridge all channels ready: {}/{}",
                ready_channels, required_channels
            );
        } else {
            println!(
                "[renium] bridge serving on {} port(s); waiting for plugin clients on demand",
                required_channels
            );
        }
        Ok((
            server,
            BridgeListenMetrics {
                bind_ms,
                wait_for_channels_ms: elapsed_ms(wait_started),
            },
        ))
    }

    fn spawn_accept_loop(
        bind_host: String,
        port: u16,
        listener: TcpListener,
        channel: Arc<BridgeChannel>,
        alive: Arc<AtomicBool>,
        request_session_id: String,
    ) {
        thread::spawn(move || {
            while alive.load(Ordering::Relaxed) {
                match listener.accept() {
                    Ok((stream, addr)) => {
                        let peer = addr.to_string();
                        match Self::accept_ready_socket(
                            &bind_host,
                            port,
                            stream,
                            peer.clone(),
                            &request_session_id,
                        ) {
                            Ok(socket) => {
                                let mut guard = match channel.sockets.lock() {
                                    Ok(guard) => guard,
                                    Err(poisoned) => poisoned.into_inner(),
                                };
                                let role = socket.role.clone();
                                let socket_key =
                                    Self::bridge_socket_key(&guard, &role, &socket.peer);
                                if socket_key == role {
                                    println!(
                                        "[renium] bridge channel ready on {}:{} role={} from {} build={}",
                                        bind_host,
                                        port,
                                        socket.role,
                                        socket.peer,
                                        socket.hello_build_unix.unwrap_or(0)
                                    );
                                }
                                guard.insert(socket_key, socket);
                            }
                            Err(err) => {
                                println!(
                                    "[renium] warning: bridge channel handshake failed on {}:{} from {}: {err:#}",
                                    bind_host, port, peer
                                );
                            }
                        }
                    }
                    Err(err) if err.kind() == io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(2));
                    }
                    Err(err) => {
                        if alive.load(Ordering::Relaxed) {
                            println!(
                                "[renium] warning: listener accept failed on {}:{}: {}",
                                bind_host, port, err
                            );
                            thread::sleep(Duration::from_millis(10));
                        }
                    }
                }
            }
        });
    }

    #[cfg(windows)]
    fn spawn_focus_watcher(channels: Vec<Arc<BridgeChannel>>, alive: Arc<AtomicBool>) {
        use windows_sys::Win32::UI::WindowsAndMessaging::{
            GetForegroundWindow, GetWindowThreadProcessId,
        };

        thread::spawn(move || {
            let mut last_pid: u32 = 0;
            while alive.load(Ordering::Relaxed) {
                thread::sleep(Duration::from_millis(300));

                let multiple_plugins = channels.iter().any(|channel| {
                    let guard = match channel.sockets.lock() {
                        Ok(guard) => guard,
                        Err(poisoned) => poisoned.into_inner(),
                    };
                    guard.len() > 1
                });
                if !multiple_plugins {
                    last_pid = 0;
                    continue;
                }

                let mut pid: u32 = 0;
                unsafe {
                    let hwnd = GetForegroundWindow();
                    if hwnd.is_null() {
                        continue;
                    }
                    GetWindowThreadProcessId(hwnd, &mut pid);
                }
                if pid == 0 || pid == last_pid {
                    continue;
                }
                last_pid = pid;

                let owned_ports = local_tcp_ports_owned_by_pid(pid);
                if owned_ports.is_empty() {
                    continue;
                }

                let now = Instant::now();
                for channel in &channels {
                    let mut guard = match channel.sockets.lock() {
                        Ok(guard) => guard,
                        Err(poisoned) => poisoned.into_inner(),
                    };
                    for socket in guard.values_mut() {
                        let peer_port = socket
                            .peer
                            .rsplit_once(':')
                            .and_then(|(_, port)| port.parse::<u16>().ok());
                        if let Some(peer_port) = peer_port
                            && owned_ports.contains(&peer_port)
                        {
                            socket.last_focused_at = now;
                        }
                    }
                }
            }
        });
    }

    fn accept_ready_socket(
        bind_host: &str,
        port: u16,
        stream: TcpStream,
        peer: String,
        request_session_id: &str,
    ) -> Result<BridgeSocket> {
        let accepted_at = Instant::now();
        let _ = stream.set_nonblocking(false);
        let _ = stream.set_nodelay(true);
        let _ = stream.set_read_timeout(Some(Duration::from_secs(5)));
        let _ = stream.set_write_timeout(Some(Duration::from_secs(5)));

        let socket_config = WebSocketConfig::default()
            .read_buffer_size(256 * 1024)
            .write_buffer_size(32 * 1024)
            .max_write_buffer_size(4 * 1024 * 1024)
            .max_message_size(Some(MAX_BRIDGE_MESSAGE_BYTES))
            .max_frame_size(Some(MAX_BRIDGE_MESSAGE_BYTES))
            .accept_unmasked_frames(false);
        let socket = accept_with_config(stream, Some(socket_config))
            .with_context(|| format!("WebSocket upgrade failed on {bind_host}:{port}"))?;

        let mut bridge_socket = BridgeSocket {
            port,
            peer,
            role: BRIDGE_ROLE_UNKNOWN.to_string(),
            last_focused_at: accepted_at,
            hello_build_unix: None,
            bridge_info: BridgeInfoPayload::default(),
            request_session_id: request_session_id.to_string(),
            socket,
        };

        let bridge_info = Self::probe_bridge_info_on_socket(&mut bridge_socket)
            .with_context(|| format!("readiness getBridgeInfo failed on {bind_host}:{port}"))?;
        bridge_socket.hello_build_unix = Some(bridge_info.bridge_build_unix);
        bridge_socket.role = normalize_bridge_role(&bridge_info.bridge_role).to_string();
        bridge_socket.bridge_info = bridge_info;

        let _ = bridge_socket
            .socket
            .get_mut()
            .set_read_timeout(Some(BRIDGE_DEFAULT_RESPONSE_TIMEOUT));
        let _ = bridge_socket
            .socket
            .get_mut()
            .set_write_timeout(Some(Duration::from_secs(10)));

        Ok(bridge_socket)
    }

    fn probe_bridge_info_on_socket(bridge_socket: &mut BridgeSocket) -> Result<BridgeInfoPayload> {
        Self::probe_bridge_info_on_socket_with_id(bridge_socket, 1)
    }

    fn probe_bridge_info_on_socket_with_id(
        bridge_socket: &mut BridgeSocket,
        id: u64,
    ) -> Result<BridgeInfoPayload> {
        let value = Self::call_on_socket(bridge_socket, id, "getBridgeInfo", &json!({}))?;
        let info: BridgeInfoPayload =
            serde_json::from_value(value).context("Invalid getBridgeInfo response from plugin")?;
        validate_bridge_info(&info)?;
        Ok(info)
    }

    fn bridge_role_key_base(role_key: &str) -> &str {
        role_key
            .split_once(BRIDGE_DUPLICATE_ROLE_KEY_SEPARATOR)
            .map(|(base, _)| base)
            .unwrap_or(role_key)
    }

    fn bridge_socket_key(
        sockets: &HashMap<String, BridgeSocket>,
        role: &str,
        peer: &str,
    ) -> String {
        if !sockets.contains_key(role) {
            return role.to_string();
        }

        let now_nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_nanos())
            .unwrap_or(0);
        let peer_key = peer.replace(BRIDGE_DUPLICATE_ROLE_KEY_SEPARATOR, "_");
        let mut suffix = 0usize;
        loop {
            let candidate = format!(
                "{role}{BRIDGE_DUPLICATE_ROLE_KEY_SEPARATOR}{now_nanos:x}-{peer_key}-{suffix}"
            );
            if !sockets.contains_key(&candidate) {
                return candidate;
            }
            suffix += 1;
        }
    }

    fn role_matches_target(role_key: &str, target: BridgeTarget) -> bool {
        let role = Self::bridge_role_key_base(role_key);
        match target {
            BridgeTarget::Edit => role == BRIDGE_ROLE_EDIT,
            BridgeTarget::Main => {
                role == BRIDGE_ROLE_EDIT
                    || role == BRIDGE_ROLE_PLAY_SERVER
                    || role == BRIDGE_ROLE_UNKNOWN
            }
            BridgeTarget::Client => role == BRIDGE_ROLE_PLAY_CLIENT,
        }
    }

    fn player_matches_selector(info: &BridgeInfoPayload, selector: &str) -> bool {
        let selector = selector.trim();
        if selector.is_empty() {
            return true;
        }
        let name = info.player_name.trim();
        if !name.is_empty() && name.eq_ignore_ascii_case(selector) {
            return true;
        }
        if let Ok(index) = selector.parse::<i64>() {
            if !name.is_empty() && name.eq_ignore_ascii_case(&format!("Player{index}")) {
                return true;
            }
            if info.player_user_id == Some(-index) {
                return true;
            }
        }
        false
    }

    fn socket_matches_selector(
        role_key: &str,
        socket: &BridgeSocket,
        target: BridgeTarget,
        player: Option<&str>,
    ) -> bool {
        if !Self::role_matches_target(role_key, target) {
            return false;
        }
        if let Some(place) = place_filter()
            && !place_matches(&socket.bridge_info, &place)
        {
            return false;
        }
        match player {
            Some(selector) => Self::player_matches_selector(&socket.bridge_info, selector),
            None => true,
        }
    }

    fn distinct_places_for_selector(
        sockets: &HashMap<String, BridgeSocket>,
        target: BridgeTarget,
        player: Option<&str>,
    ) -> Vec<(Option<i64>, String)> {
        let mut places: Vec<(Option<i64>, String)> = Vec::new();
        for (role_key, socket) in sockets {
            if !Self::socket_matches_selector(role_key.as_str(), socket, target, player) {
                continue;
            }
            let info = &socket.bridge_info;
            if info.place_name.trim().is_empty() && info.place_id.is_none() {
                continue;
            }
            let entry = (info.place_id, info.place_name.clone());
            if !places.contains(&entry) {
                places.push(entry);
            }
        }
        places
    }

    fn ensure_place_unambiguous(
        sockets: &mut HashMap<String, BridgeSocket>,
        target: BridgeTarget,
        player: Option<&str>,
    ) -> Result<()> {
        let mut places = Self::distinct_places_for_selector(sockets, target, player);
        if places.len() > 1 {
            let dead_keys: Vec<String> = sockets
                .iter_mut()
                .filter_map(|(key, socket)| {
                    if Self::socket_is_alive(socket) {
                        None
                    } else {
                        Some(key.clone())
                    }
                })
                .collect();
            for key in dead_keys {
                if let Some(mut dead_socket) = sockets.remove(&key) {
                    Self::close_socket(&mut dead_socket);
                }
            }
            places = Self::distinct_places_for_selector(sockets, target, player);
        }
        if places.len() > 1 {
            let listing = places
                .iter()
                .map(|(id, name)| match id {
                    Some(id) => format!("'{name}' (placeId {id})"),
                    None => format!("'{name}'"),
                })
                .collect::<Vec<_>>()
                .join(", ");
            bail!(
                "Multiple Studio places are connected and match this command: {listing}. Pin \
                 commands to one place with --place <name|id> or the RENIUM_PLACE env var"
            );
        }
        Ok(())
    }

    fn target_label(target: BridgeTarget) -> &'static str {
        match target {
            BridgeTarget::Edit => "edit",
            BridgeTarget::Main => "main",
            BridgeTarget::Client => "play-client",
        }
    }

    fn role_preference_rank(role_key: &str, target: BridgeTarget) -> usize {
        let role = Self::bridge_role_key_base(role_key);
        match target {
            BridgeTarget::Edit => usize::from(role != BRIDGE_ROLE_EDIT),
            BridgeTarget::Main => match role {
                BRIDGE_ROLE_PLAY_SERVER => 0,
                BRIDGE_ROLE_EDIT => 1,
                BRIDGE_ROLE_UNKNOWN => 2,
                _ => 3,
            },
            BridgeTarget::Client => usize::from(role != BRIDGE_ROLE_PLAY_CLIENT),
        }
    }

    fn runtime_pin_key(target: BridgeTarget, player: Option<&str>) -> RuntimePinKey {
        RuntimePinKey {
            target,
            player: player.map(|value| value.trim().to_ascii_lowercase()),
        }
    }

    fn clear_runtime_pins(&self) {
        self.runtime_pins
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .clear();
    }

    fn choose_runtime_pin(&self, target: BridgeTarget, player: Option<&str>) -> Result<RuntimePin> {
        let mut candidates: HashMap<String, RuntimePinCandidate> = HashMap::new();
        let mut legacy_candidate: Option<(u16, String, Instant)> = None;
        let mut legacy_ambiguous = false;
        let mut matching_socket_count = 0usize;

        for channel in &self.channels {
            let mut guard = channel
                .sockets
                .lock()
                .unwrap_or_else(|error| error.into_inner());
            Self::ensure_place_unambiguous(&mut guard, target, player)?;
            let matching = guard
                .iter()
                .filter(|(role_key, socket)| {
                    Self::socket_matches_selector(role_key.as_str(), socket, target, player)
                })
                .map(|(role_key, socket)| (role_key.clone(), socket))
                .collect::<Vec<_>>();
            matching_socket_count += matching.len();

            let legacy = matching
                .iter()
                .filter(|(_, socket)| socket.bridge_info.runtime_id.trim().is_empty())
                .collect::<Vec<_>>();
            if legacy.len() == 1 {
                let (role_key, socket) = legacy[0];
                if legacy_candidate
                    .as_ref()
                    .is_none_or(|(_, _, focused_at)| *focused_at < socket.last_focused_at)
                {
                    legacy_candidate =
                        Some((channel.port, role_key.clone(), socket.last_focused_at));
                }
            } else if legacy.len() > 1 {
                legacy_ambiguous = true;
            }

            for (role_key, socket) in matching {
                let runtime_id = socket.bridge_info.runtime_id.trim();
                if runtime_id.is_empty() {
                    continue;
                }
                let role_rank = Self::role_preference_rank(&role_key, target);
                let candidate = candidates.entry(runtime_id.to_string()).or_insert_with(|| {
                    RuntimePinCandidate {
                        runtime_id: runtime_id.to_string(),
                        socket_keys_by_port: HashMap::new(),
                        role_rank,
                        last_focused_at: socket.last_focused_at,
                    }
                });
                let replace_existing = candidate
                    .socket_keys_by_port
                    .get(&channel.port)
                    .and_then(|existing_key| guard.get(existing_key))
                    .is_none_or(|existing| existing.last_focused_at < socket.last_focused_at);
                if replace_existing {
                    candidate.socket_keys_by_port.insert(channel.port, role_key);
                }
                candidate.role_rank = candidate.role_rank.min(role_rank);
                candidate.last_focused_at = candidate.last_focused_at.max(socket.last_focused_at);
            }
        }

        if let Some(candidate) = candidates.into_values().max_by(|left, right| {
            right
                .role_rank
                .cmp(&left.role_rank)
                .then_with(|| left.last_focused_at.cmp(&right.last_focused_at))
                .then_with(|| {
                    left.socket_keys_by_port
                        .len()
                        .cmp(&right.socket_keys_by_port.len())
                })
        }) {
            return Ok(RuntimePin {
                runtime_id: Some(candidate.runtime_id),
                socket_keys_by_port: candidate.socket_keys_by_port,
            });
        }

        if matching_socket_count == 0 {
            bail!(
                "No connected {} bridge{} found",
                Self::target_label(target),
                player
                    .map(|selector| format!(" for player {selector}"))
                    .unwrap_or_default()
            );
        }
        if legacy_ambiguous {
            bail!(
                "Multiple matching Studio runtimes use an older bridge without runtime identity. \
                 Update the Renium Studio plugin before using multiple Studio windows"
            );
        }
        let Some((channel_port, role_key, _)) = legacy_candidate else {
            bail!(
                "Matching bridge channels could not be associated with one Studio runtime; \
                 reconnect or update the Renium Studio plugin"
            );
        };
        Ok(RuntimePin {
            runtime_id: None,
            socket_keys_by_port: HashMap::from([(channel_port, role_key)]),
        })
    }

    fn runtime_pin_for_selector(
        &self,
        target: BridgeTarget,
        player: Option<&str>,
    ) -> Result<RuntimePin> {
        let key = Self::runtime_pin_key(target, player);
        let mut pins = self
            .runtime_pins
            .lock()
            .unwrap_or_else(|error| error.into_inner());
        if let Some(pin) = pins.get(&key) {
            return Ok(pin.clone());
        }
        let pin = self.choose_runtime_pin(target, player)?;
        pins.insert(key, pin.clone());
        Ok(pin)
    }

    fn socket_matches_runtime_pin(
        channel_port: u16,
        role_key: &str,
        socket: &BridgeSocket,
        pin: &RuntimePin,
    ) -> bool {
        if let Some(runtime_id) = pin.runtime_id.as_deref() {
            return socket.bridge_info.runtime_id == runtime_id;
        }
        pin.socket_keys_by_port
            .get(&channel_port)
            .is_some_and(|key| key == role_key)
    }

    fn select_role_for_selector_with_pin(
        sockets: &HashMap<String, BridgeSocket>,
        channel_port: u16,
        target: BridgeTarget,
        player: Option<&str>,
        pin: &RuntimePin,
    ) -> Option<String> {
        let preferred: &[&str] = match target {
            BridgeTarget::Edit => &[BRIDGE_ROLE_EDIT],
            BridgeTarget::Main => &[
                BRIDGE_ROLE_PLAY_SERVER,
                BRIDGE_ROLE_EDIT,
                BRIDGE_ROLE_UNKNOWN,
            ],
            BridgeTarget::Client => &[BRIDGE_ROLE_PLAY_CLIENT],
        };
        for role in preferred {
            if let Some(key) = sockets
                .iter()
                .filter(|(key, socket)| {
                    Self::bridge_role_key_base(key.as_str()) == *role
                        && Self::socket_matches_selector(key.as_str(), socket, target, player)
                        && Self::socket_matches_runtime_pin(channel_port, key.as_str(), socket, pin)
                })
                .max_by_key(|(_, socket)| socket.last_focused_at)
                .map(|(key, _)| key.clone())
            {
                return Some(key);
            }
        }
        sockets
            .iter()
            .filter(|(key, socket)| {
                Self::socket_matches_selector(key.as_str(), socket, target, player)
                    && Self::socket_matches_runtime_pin(channel_port, key.as_str(), socket, pin)
            })
            .max_by_key(|(_, socket)| socket.last_focused_at)
            .map(|(key, _)| key.clone())
    }

    fn select_role_for_target(
        sockets: &HashMap<String, BridgeSocket>,
        target: BridgeTarget,
    ) -> Option<String> {
        Self::select_role_for_selector(sockets, target, None)
    }

    fn select_role_for_selector(
        sockets: &HashMap<String, BridgeSocket>,
        target: BridgeTarget,
        player: Option<&str>,
    ) -> Option<String> {
        let preferred: &[&str] = match target {
            BridgeTarget::Edit => &[BRIDGE_ROLE_EDIT],
            BridgeTarget::Main => &[
                BRIDGE_ROLE_PLAY_SERVER,
                BRIDGE_ROLE_EDIT,
                BRIDGE_ROLE_UNKNOWN,
            ],
            BridgeTarget::Client => &[BRIDGE_ROLE_PLAY_CLIENT],
        };
        for role in preferred {
            let newest = sockets
                .iter()
                .filter(|(key, socket)| {
                    Self::bridge_role_key_base(key.as_str()) == *role
                        && Self::socket_matches_selector(key.as_str(), socket, target, player)
                })
                .max_by_key(|(_, socket)| socket.last_focused_at)
                .map(|(key, _)| key.clone());
            if newest.is_some() {
                return newest;
            }
        }
        sockets
            .iter()
            .filter(|(role, socket)| {
                Self::socket_matches_selector(role.as_str(), socket, target, player)
            })
            .max_by_key(|(_, socket)| socket.last_focused_at)
            .map(|(role, _)| role.clone())
    }

    fn wait_for_ready_channels_for_target(
        &self,
        required_channels: usize,
        timeout: Duration,
        target: BridgeTarget,
    ) -> usize {
        let deadline = Instant::now() + timeout;
        loop {
            let ready_channels = self.channel_count_for_target(target);
            if ready_channels >= required_channels || Instant::now() >= deadline {
                return ready_channels;
            }
            thread::sleep(Duration::from_millis(2));
        }
    }

    #[expect(
        dead_code,
        reason = "compatibility wrapper retained for callers targeting the main bridge"
    )]
    fn wait_for_ready_channels(&self, required_channels: usize, timeout: Duration) -> usize {
        self.wait_for_ready_channels_for_target(required_channels, timeout, BridgeTarget::Main)
    }

    fn peer_for_selector(&self, target: BridgeTarget, player: Option<&str>) -> Result<String> {
        let runtime_pin = self.runtime_pin_for_selector(target, player)?;
        for channel in &self.channels {
            let mut guard = match channel.sockets.try_lock() {
                Ok(guard) => guard,
                Err(TryLockError::Poisoned(poisoned)) => poisoned.into_inner(),
                Err(TryLockError::WouldBlock) => continue,
            };
            Self::ensure_place_unambiguous(&mut guard, target, player)?;
            if let Some(role) = Self::select_role_for_selector_with_pin(
                &guard,
                channel.port,
                target,
                player,
                &runtime_pin,
            ) && let Some(socket) = guard.get(&role)
            {
                return Ok(socket.peer.clone());
            }
        }
        bail!(
            "No connected {} bridge{} found",
            Self::target_label(target),
            player
                .map(|selector| format!(" for player {selector}"))
                .unwrap_or_default()
        )
    }

    fn cached_bridge_info_for_target(&self, target: BridgeTarget) -> Result<BridgeInfoPayload> {
        let runtime_pin = self.runtime_pin_for_selector(target, None)?;
        for channel in &self.channels {
            let guard = match channel.sockets.try_lock() {
                Ok(guard) => guard,
                Err(TryLockError::Poisoned(poisoned)) => poisoned.into_inner(),
                Err(TryLockError::WouldBlock) => continue,
            };
            if let Some(role) = Self::select_role_for_selector_with_pin(
                &guard,
                channel.port,
                target,
                None,
                &runtime_pin,
            ) && let Some(socket) = guard.get(&role)
            {
                return Ok(socket.bridge_info.clone());
            }
        }
        bail!(
            "No cached {} plugin bridge info is available; no ready bridge channels",
            Self::target_label(target)
        );
    }

    fn cached_bridge_info(&self) -> Result<BridgeInfoPayload> {
        self.cached_bridge_info_for_target(BridgeTarget::Main)
    }

    fn cache_export_options_for_target(
        &self,
        target: BridgeTarget,
        performance_mode: &str,
        modified_default_bypass: bool,
        export_all_properties: bool,
    ) {
        let Ok(runtime_pin) = self.runtime_pin_for_selector(target, None) else {
            return;
        };
        for channel in &self.channels {
            let mut guard = channel
                .sockets
                .lock()
                .unwrap_or_else(|error| error.into_inner());
            for (role_key, socket) in guard.iter_mut() {
                if Self::socket_matches_selector(role_key, socket, target, None)
                    && Self::socket_matches_runtime_pin(
                        channel.port,
                        role_key,
                        socket,
                        &runtime_pin,
                    )
                {
                    socket.bridge_info.performance_mode = performance_mode.to_string();
                    socket.bridge_info.modified_default_bypass = modified_default_bypass;
                    socket.bridge_info.export_all_properties = export_all_properties;
                    socket.bridge_info.pre_serialize_on_prepare = false;
                    socket.bridge_info.pre_serialize_large_service_warm = false;
                }
            }
        }
    }

    fn expected_channel_count(&self) -> usize {
        self.channels.len()
    }

    fn missing_ports_for_target(&self, target: BridgeTarget) -> Vec<u16> {
        self.channels
            .iter()
            .filter_map(|channel| {
                let guard = match channel.sockets.try_lock() {
                    Ok(guard) => guard,
                    Err(TryLockError::Poisoned(poisoned)) => poisoned.into_inner(),
                    Err(TryLockError::WouldBlock) => return None,
                };
                if Self::select_role_for_target(&guard, target).is_some() {
                    None
                } else {
                    Some(channel.port)
                }
            })
            .collect()
    }

    fn missing_ports(&self) -> Vec<u16> {
        self.missing_ports_for_target(BridgeTarget::Main)
    }

    fn close_socket(socket: &mut BridgeSocket) {
        let _ = socket.socket.close(None);
        let _ = socket.socket.get_mut().shutdown(Shutdown::Both);
    }

    fn is_transport_error_text(text: &str) -> bool {
        text.contains("Bridge send failed")
            || text.contains("Bridge read failed")
            || text.contains("Bridge closed while waiting")
            || text.contains("Connection reset")
            || text.contains("connection reset")
            || text.contains("Broken pipe")
            || text.contains("broken pipe")
            || text.contains("WouldBlock")
            || text.contains("TimedOut")
            || text.contains("timed out")
    }

    fn call(&self, method: &str, params: Value) -> Result<Value> {
        self.call_for_target(method, params, BridgeTarget::Main)
    }

    fn call_for_target(&self, method: &str, params: Value, target: BridgeTarget) -> Result<Value> {
        self.call_for_selector(method, params, target, None)
    }

    fn call_for_selector(
        &self,
        method: &str,
        params: Value,
        target: BridgeTarget,
        player: Option<&str>,
    ) -> Result<Value> {
        if self.channels.is_empty() {
            bail!("No active bridge sockets");
        }

        let runtime_pin = if method == "startStopPlay" {
            None
        } else {
            Some(self.runtime_pin_for_selector(target, player)?)
        };
        let id = self
            .next_id
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let total = self.channels.len();
        let start = self
            .preferred_index
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed)
            % total;

        let mut last_error: Option<String> = None;
        for _ in 0..64 {
            for offset in 0..total {
                let index = (start + offset) % total;
                let channel = &self.channels[index];
                let mut guard = match channel.sockets.try_lock() {
                    Ok(guard) => guard,
                    Err(TryLockError::Poisoned(poisoned)) => poisoned.into_inner(),
                    Err(TryLockError::WouldBlock) => continue,
                };
                Self::ensure_place_unambiguous(&mut guard, target, player)?;
                let socket_role = match runtime_pin.as_ref() {
                    Some(pin) => Self::select_role_for_selector_with_pin(
                        &guard,
                        channel.port,
                        target,
                        player,
                        pin,
                    ),
                    None => Self::select_role_for_selector(&guard, target, player),
                };
                let Some(socket_role) = socket_role else {
                    continue;
                };
                let Some(socket) = guard.get_mut(&socket_role) else {
                    continue;
                };
                let socket_port = socket.port;
                let role = socket.role.clone();
                let call_result = Self::call_on_socket(socket, id, method, &params);
                match call_result {
                    Ok(result) => {
                        return Ok(result);
                    }
                    Err(err) => {
                        let err_text = format!("{err:#}");
                        if !Self::is_transport_error_text(&err_text) {
                            return Err(err);
                        }
                        last_error = Some(format!("port {socket_port} role {role}: {err_text}"));
                        if let Some(mut dead_socket) = guard.remove(&socket_role) {
                            Self::close_socket(&mut dead_socket);
                        }
                    }
                }
            }
            thread::yield_now();
        }

        let lock_deadline = Instant::now() + bridge_channel_lock_timeout(method);
        while Instant::now() < lock_deadline {
            let mut attempted_socket = false;
            for offset in 0..total {
                let index = (start + offset) % total;
                let channel = &self.channels[index];
                let mut guard = match channel.sockets.try_lock() {
                    Ok(guard) => guard,
                    Err(TryLockError::Poisoned(poisoned)) => poisoned.into_inner(),
                    Err(TryLockError::WouldBlock) => continue,
                };
                let socket_role = match runtime_pin.as_ref() {
                    Some(pin) => Self::select_role_for_selector_with_pin(
                        &guard,
                        channel.port,
                        target,
                        player,
                        pin,
                    ),
                    None => Self::select_role_for_selector(&guard, target, player),
                };
                let Some(socket_role) = socket_role else {
                    continue;
                };
                let Some(socket) = guard.get_mut(&socket_role) else {
                    continue;
                };
                attempted_socket = true;
                let socket_port = socket.port;
                let role = socket.role.clone();
                let call_result = Self::call_on_socket(socket, id, method, &params);
                match call_result {
                    Ok(result) => return Ok(result),
                    Err(err) => {
                        let err_text = format!("{err:#}");
                        if !Self::is_transport_error_text(&err_text) {
                            return Err(err);
                        }
                        last_error = Some(format!("port {socket_port} role {role}: {err_text}"));
                        if let Some(mut dead_socket) = guard.remove(&socket_role) {
                            Self::close_socket(&mut dead_socket);
                        }
                    }
                }
            }
            if !attempted_socket && last_error.is_none() {
                last_error = Some("all compatible bridge channels are busy".to_string());
            }
            thread::sleep(Duration::from_millis(2));
        }

        bail!(
            "Bridge call failed for {method} on {} target{}: {}",
            Self::target_label(target),
            player
                .map(|selector| format!(" (player {selector})"))
                .unwrap_or_default(),
            last_error.unwrap_or_else(|| {
                if runtime_pin.is_some() {
                    "the pinned Studio runtime disconnected or has no available channel".to_string()
                } else {
                    "no active channels".to_string()
                }
            })
        )
    }

    fn channel_count_for_target(&self, target: BridgeTarget) -> usize {
        self.channel_count_for_selector(target, None)
    }

    fn channel_count_for_selector(&self, target: BridgeTarget, player: Option<&str>) -> usize {
        self.channels
            .iter()
            .filter(|channel| {
                let guard = match channel.sockets.try_lock() {
                    Ok(guard) => guard,
                    Err(TryLockError::Poisoned(poisoned)) => poisoned.into_inner(),
                    Err(TryLockError::WouldBlock) => return true,
                };
                Self::select_role_for_selector(&guard, target, player).is_some()
            })
            .count()
    }

    fn wait_for_ready_player(&self, player: &str, timeout: Duration) -> bool {
        let deadline = Instant::now() + timeout;
        loop {
            if self.channel_count_for_selector(BridgeTarget::Client, Some(player)) >= 1 {
                return true;
            }
            if Instant::now() >= deadline {
                return false;
            }
            thread::sleep(Duration::from_millis(20));
        }
    }

    fn socket_is_alive(socket: &mut BridgeSocket) -> bool {
        let stream = socket.socket.get_ref();
        if stream.set_nonblocking(true).is_err() {
            return true;
        }
        let mut probe = [0u8; 1];
        let peek = stream.peek(&mut probe);
        let _ = stream.set_nonblocking(false);
        match peek {
            Ok(0) => false,
            Err(err) if err.kind() != io::ErrorKind::WouldBlock => false,
            _ => {
                socket.socket.send(Message::Ping(Vec::new().into())).is_ok()
                    && socket.socket.flush().is_ok()
            }
        }
    }

    fn list_bridge_clients(&self) -> Vec<Value> {
        struct ClientEntry {
            runtime_id: String,
            role: String,
            player_name: String,
            player_user_id: Option<i64>,
            place_id: Option<i64>,
            place_name: String,
            build_unix: i64,
            ports: Vec<u16>,
        }
        let mut entries: Vec<ClientEntry> = Vec::new();
        for channel in &self.channels {
            let mut guard = match channel.sockets.try_lock() {
                Ok(guard) => guard,
                Err(TryLockError::Poisoned(poisoned)) => poisoned.into_inner(),
                Err(TryLockError::WouldBlock) => continue,
            };
            let mut dead_keys = Vec::new();
            for (role_key, socket) in guard.iter_mut() {
                if !Self::socket_is_alive(socket) {
                    dead_keys.push(role_key.clone());
                    continue;
                }
                if Self::bridge_role_key_base(role_key) == BRIDGE_ROLE_PLAY_CLIENT
                    && socket.bridge_info.player_name.trim().is_empty()
                {
                    let id = self
                        .next_id
                        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    if let Ok(info) = Self::probe_bridge_info_on_socket_with_id(socket, id) {
                        socket.role = normalize_bridge_role(&info.bridge_role).to_string();
                        socket.bridge_info = info;
                    }
                }
            }
            for key in dead_keys {
                if let Some(mut dead_socket) = guard.remove(&key) {
                    Self::close_socket(&mut dead_socket);
                }
            }
            for (role_key, socket) in guard.iter() {
                let role = Self::bridge_role_key_base(role_key).to_string();
                let info = &socket.bridge_info;
                let existing = entries.iter_mut().find(|entry| {
                    entry.runtime_id == info.runtime_id
                        && entry.role == role
                        && entry.player_name == info.player_name
                        && entry.player_user_id == info.player_user_id
                        && entry.place_id == info.place_id
                        && entry.place_name == info.place_name
                });
                match existing {
                    Some(entry) => {
                        if !entry.ports.contains(&socket.port) {
                            entry.ports.push(socket.port);
                        }
                    }
                    None => entries.push(ClientEntry {
                        runtime_id: info.runtime_id.clone(),
                        role,
                        player_name: info.player_name.clone(),
                        player_user_id: info.player_user_id,
                        place_id: info.place_id,
                        place_name: info.place_name.clone(),
                        build_unix: info.bridge_build_unix,
                        ports: vec![socket.port],
                    }),
                }
            }
        }
        entries.sort_by(|a, b| {
            (&a.place_name, &a.role, &a.player_name, &a.runtime_id).cmp(&(
                &b.place_name,
                &b.role,
                &b.player_name,
                &b.runtime_id,
            ))
        });
        entries
            .into_iter()
            .map(|mut entry| {
                entry.ports.sort_unstable();
                let mut object = serde_json::Map::new();
                if !entry.runtime_id.is_empty() {
                    object.insert("runtimeId".to_string(), json!(entry.runtime_id));
                }
                object.insert("role".to_string(), json!(entry.role));
                if !entry.player_name.is_empty() {
                    object.insert("playerName".to_string(), json!(entry.player_name));
                }
                if let Some(user_id) = entry.player_user_id {
                    object.insert("playerUserId".to_string(), json!(user_id));
                }
                if !entry.place_name.is_empty() {
                    object.insert("placeName".to_string(), json!(entry.place_name));
                }
                if let Some(place_id) = entry.place_id {
                    object.insert("placeId".to_string(), json!(place_id));
                }
                object.insert("bridgeBuildUnix".to_string(), json!(entry.build_unix));
                object.insert("channels".to_string(), json!(entry.ports.len()));
                object.insert("ports".to_string(), json!(entry.ports));
                Value::Object(object)
            })
            .collect()
    }

    fn channel_count(&self) -> usize {
        self.channel_count_for_target(BridgeTarget::Main)
    }

    fn call_chunk(&self, method: &str, params: Value) -> Result<BridgeChunk> {
        self.call_chunk_for_target(method, params, BridgeTarget::Main)
    }

    fn call_chunk_for_target(
        &self,
        method: &str,
        params: Value,
        target: BridgeTarget,
    ) -> Result<BridgeChunk> {
        if self.channels.is_empty() {
            bail!("No active bridge sockets");
        }
        let runtime_pin = self.runtime_pin_for_selector(target, None)?;

        let id = self
            .next_id
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let total = self.channels.len();
        let start = self
            .preferred_index
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed)
            % total;

        let mut last_error: Option<String> = None;
        for _ in 0..64 {
            for offset in 0..total {
                let index = (start + offset) % total;
                let channel = &self.channels[index];
                let mut guard = match channel.sockets.try_lock() {
                    Ok(guard) => guard,
                    Err(TryLockError::Poisoned(poisoned)) => poisoned.into_inner(),
                    Err(TryLockError::WouldBlock) => continue,
                };
                let Some(socket_role) = Self::select_role_for_selector_with_pin(
                    &guard,
                    channel.port,
                    target,
                    None,
                    &runtime_pin,
                ) else {
                    continue;
                };
                let Some(socket) = guard.get_mut(&socket_role) else {
                    continue;
                };
                let socket_port = socket.port;
                let role = socket.role.clone();
                let call_result = Self::call_on_socket_chunk(socket, id, method, &params);
                match call_result {
                    Ok(result) => {
                        return Ok(result);
                    }
                    Err(err) => {
                        let err_text = format!("{err:#}");
                        if !Self::is_transport_error_text(&err_text) {
                            return Err(err);
                        }
                        last_error = Some(format!("port {socket_port} role {role}: {err_text}"));
                        if let Some(mut dead_socket) = guard.remove(&socket_role) {
                            Self::close_socket(&mut dead_socket);
                        }
                    }
                }
            }
            thread::yield_now();
        }

        let lock_deadline = Instant::now() + bridge_channel_lock_timeout(method);
        while Instant::now() < lock_deadline {
            let mut attempted_socket = false;
            for offset in 0..total {
                let index = (start + offset) % total;
                let channel = &self.channels[index];
                let mut guard = match channel.sockets.try_lock() {
                    Ok(guard) => guard,
                    Err(TryLockError::Poisoned(poisoned)) => poisoned.into_inner(),
                    Err(TryLockError::WouldBlock) => continue,
                };
                let Some(socket_role) = Self::select_role_for_selector_with_pin(
                    &guard,
                    channel.port,
                    target,
                    None,
                    &runtime_pin,
                ) else {
                    continue;
                };
                let Some(socket) = guard.get_mut(&socket_role) else {
                    continue;
                };
                attempted_socket = true;
                let socket_port = socket.port;
                let role = socket.role.clone();
                let call_result = Self::call_on_socket_chunk(socket, id, method, &params);
                match call_result {
                    Ok(result) => return Ok(result),
                    Err(err) => {
                        let err_text = format!("{err:#}");
                        if !Self::is_transport_error_text(&err_text) {
                            return Err(err);
                        }
                        last_error = Some(format!("port {socket_port} role {role}: {err_text}"));
                        if let Some(mut dead_socket) = guard.remove(&socket_role) {
                            Self::close_socket(&mut dead_socket);
                        }
                    }
                }
            }
            if !attempted_socket && last_error.is_none() {
                last_error = Some("all compatible bridge channels are busy".to_string());
            }
            thread::sleep(Duration::from_millis(2));
        }

        bail!(
            "Bridge chunk call failed for {method} on {} target: {}",
            Self::target_label(target),
            last_error.unwrap_or_else(|| {
                "the pinned Studio runtime disconnected or has no available channel".to_string()
            })
        )
    }

    fn call_on_socket(
        bridge_socket: &mut BridgeSocket,
        id: u64,
        method: &str,
        params: &Value,
    ) -> Result<Value> {
        Self::configure_request_timeout(bridge_socket, method);
        Self::send_request(bridge_socket, id, method, params)?;

        match Self::read_response(bridge_socket, id, method, bridge_response_timeout(method))? {
            BridgeResponse::Json(result) => Ok(result),
            BridgeResponse::Chunk(_) => {
                bail!("Bridge method {method} returned a raw chunk response unexpectedly");
            }
        }
    }

    fn call_on_socket_chunk(
        bridge_socket: &mut BridgeSocket,
        id: u64,
        method: &str,
        params: &Value,
    ) -> Result<BridgeChunk> {
        Self::configure_request_timeout(bridge_socket, method);
        Self::send_request(bridge_socket, id, method, params)?;

        match Self::read_response(bridge_socket, id, method, bridge_response_timeout(method))? {
            BridgeResponse::Chunk(chunk) => Ok(chunk),
            BridgeResponse::Json(result) => parse_bridge_chunk(result),
        }
    }

    fn configure_request_timeout(bridge_socket: &mut BridgeSocket, method: &str) {
        let timeout = bridge_response_timeout(method);
        let _ = bridge_socket
            .socket
            .get_mut()
            .set_read_timeout(Some(timeout));
        let _ = bridge_socket
            .socket
            .get_mut()
            .set_write_timeout(Some(Duration::from_secs(10)));
    }

    fn send_request(
        bridge_socket: &mut BridgeSocket,
        id: u64,
        method: &str,
        params: &Value,
    ) -> Result<()> {
        #[derive(Serialize)]
        struct BridgeRequest<'a> {
            id: u64,
            session_id: &'a str,
            method: &'a str,
            params: &'a Value,
        }

        let payload = serde_json::to_string(&BridgeRequest {
            id,
            session_id: &bridge_socket.request_session_id,
            method,
            params,
        })?;
        if payload.len() > MAX_BRIDGE_REQUEST_BYTES {
            bail!(
                "Bridge request for {method} is {} bytes, above the {MAX_BRIDGE_REQUEST_BYTES}-byte safety limit",
                payload.len()
            );
        }

        bridge_socket
            .socket
            .send(Message::Text(payload.into()))
            .with_context(|| {
                format!(
                    "Bridge send failed for method {method} on port {}",
                    bridge_socket.port
                )
            })?;
        Ok(())
    }

    fn read_response(
        bridge_socket: &mut BridgeSocket,
        id: u64,
        method: &str,
        timeout: Duration,
    ) -> Result<BridgeResponse> {
        let deadline = Instant::now() + timeout;
        let mut unrelated_messages = 0usize;
        loop {
            if Instant::now() >= deadline {
                bail!(
                    "Bridge response timed out awaiting {method} on port {} after {:.1}s",
                    bridge_socket.port,
                    timeout.as_secs_f64()
                );
            }
            let message = bridge_socket.socket.read().with_context(|| {
                format!(
                    "Bridge read failed for method {method} on port {}",
                    bridge_socket.port
                )
            })?;
            match message {
                Message::Text(text) => {
                    if text.starts_with("RBS1 ") {
                        if let Some((raw_id, chunk)) = parse_bridge_raw_chunk(text.to_string())? {
                            if raw_id != id {
                                unrelated_messages = unrelated_messages.saturating_add(1);
                                if unrelated_messages > MAX_BRIDGE_UNRELATED_MESSAGES {
                                    bail!(
                                        "Bridge sent too many unrelated responses while waiting for {method}"
                                    );
                                }
                                continue;
                            }
                            return Ok(BridgeResponse::Chunk(chunk));
                        }
                        continue;
                    }

                    let mut parsed: Value =
                        serde_json::from_str(text.as_str()).with_context(|| {
                            format!("Invalid bridge JSON message ({} bytes)", text.len())
                        })?;
                    let msg_id = parsed.get("id").and_then(Value::as_u64);
                    if msg_id != Some(id) {
                        unrelated_messages = unrelated_messages.saturating_add(1);
                        if unrelated_messages > MAX_BRIDGE_UNRELATED_MESSAGES {
                            bail!(
                                "Bridge sent too many unrelated responses while waiting for {method}"
                            );
                        }
                        continue;
                    }
                    let ok = parsed.get("ok").and_then(Value::as_bool).unwrap_or(false);
                    if ok {
                        let result = parsed
                            .as_object_mut()
                            .and_then(|object| object.remove("result"))
                            .unwrap_or(Value::Null);
                        return Ok(BridgeResponse::Json(result));
                    }
                    let err = parsed
                        .get("error")
                        .and_then(Value::as_str)
                        .unwrap_or("bridge error");
                    bail!("Bridge method {method} failed: {err}");
                }
                Message::Ping(payload) => {
                    let _ = bridge_socket.socket.send(Message::Pong(payload));
                    continue;
                }
                Message::Binary(_) | Message::Pong(_) | Message::Frame(_) => {
                    continue;
                }
                Message::Close(frame) => {
                    bail!("Bridge closed while waiting for {method}: {frame:?}");
                }
            }
        }
    }
}

impl Drop for BridgeServer {
    fn drop(&mut self) {
        self.alive.store(false, Ordering::Relaxed);
        for channel in &self.channels {
            let mut guard = match channel.sockets.lock() {
                Ok(guard) => guard,
                Err(poisoned) => poisoned.into_inner(),
            };
            for (_, mut socket) in guard.drain() {
                BridgeServer::close_socket(&mut socket);
            }
        }
    }
}

fn parse_bridge_raw_chunk(mut text: String) -> Result<Option<(u64, BridgeChunk)>> {
    if !text.starts_with("RBS1 ") {
        return Ok(None);
    }

    let payload_index = text
        .find('\n')
        .map(|index| index + 1)
        .with_context(|| "Invalid raw bridge frame: missing payload separator")?;
    let (id, start, next_start, total, plugin_server_ms, plugin_encode_ms) = {
        let header = &text["RBS1 ".len()..payload_index - 1];
        let mut parts = header.split_whitespace();
        let id = parts
            .next()
            .with_context(|| "Invalid raw bridge frame: missing header fields")?
            .parse::<u64>()
            .context("Invalid raw bridge frame id")?;
        let start = parts
            .next()
            .with_context(|| "Invalid raw bridge frame: missing header fields")?
            .parse::<usize>()
            .context("Invalid raw bridge frame start")?;
        let next_start = parts
            .next()
            .with_context(|| "Invalid raw bridge frame: missing header fields")?
            .parse::<usize>()
            .context("Invalid raw bridge frame next start")?;
        let total = parts
            .next()
            .with_context(|| "Invalid raw bridge frame: missing header fields")?
            .parse::<usize>()
            .context("Invalid raw bridge frame total")?;
        let plugin_server_ms = parts.next().and_then(|value| value.parse::<f64>().ok());
        let plugin_encode_ms = parts.next().and_then(|value| value.parse::<f64>().ok());
        if parts.next().is_some() {
            bail!("Invalid raw bridge frame: too many header fields");
        }
        (
            id,
            start,
            next_start,
            total,
            plugin_server_ms,
            plugin_encode_ms,
        )
    };
    let payload = text.split_off(payload_index);
    let chunk = BridgeChunk {
        start,
        next_start: if total == 0 { start } else { next_start },
        total,
        chunk: payload,
        plugin_server_ms,
        plugin_encode_ms,
    };
    validate_bridge_chunk(&chunk)?;
    Ok(Some((id, chunk)))
}

