#[cfg(windows)]
fn cursor_poll(args: CursorPollArgs) -> Result<()> {
    use windows_sys::Win32::Foundation::{POINT, RECT};
    use windows_sys::Win32::UI::Input::KeyboardAndMouse::{GetKeyState, VK_LBUTTON};
    use windows_sys::Win32::UI::WindowsAndMessaging::{
        GetCursorPos, GetWindowRect, WindowFromPoint,
    };

    let interval = Duration::from_millis(args.interval_ms.max(1));
    let mut stdout = io::BufWriter::new(io::stdout().lock());
    loop {
        let mut point = POINT { x: 0, y: 0 };
        let got_cursor = unsafe { GetCursorPos(&mut point) } != 0;
        if got_cursor {
            let hwnd = unsafe { WindowFromPoint(point) };
            let mut rect = RECT {
                left: 0,
                top: 0,
                right: 0,
                bottom: 0,
            };
            if !hwnd.is_null() {
                unsafe {
                    GetWindowRect(hwnd, &mut rect);
                }
            }
            let left_down = unsafe { GetKeyState(VK_LBUTTON as i32) } as u16 & 0x8000 != 0;
            if writeln!(
                stdout,
                "{},{},{},{},{},{},{}",
                point.x,
                point.y,
                rect.left,
                rect.top,
                rect.right,
                rect.bottom,
                if left_down { 1 } else { 0 }
            )
            .is_err()
            {
                break;
            }
            if stdout.flush().is_err() {
                break;
            }
        }
        thread::sleep(interval);
    }
    Ok(())
}

#[cfg(not(windows))]
fn cursor_poll(_args: CursorPollArgs) -> Result<()> {
    bail!("cursor-poll is only supported on Windows")
}

fn parse_daemon_request_args<T: Parser>(command: &str, request_args: &[String]) -> Result<T> {
    let mut argv = Vec::with_capacity(request_args.len() + 1);
    argv.push(command.to_string());
    argv.extend(request_args.iter().cloned());
    T::try_parse_from(argv).map_err(|err| anyhow::anyhow!(err.to_string()))
}

fn bridge_daemon(args: BridgeDaemonArgs) -> Result<()> {
    let editor_stdio = args.editor_stdio;
    if let Some(parent_pid) = args.parent_pid {
        watch_parent_and_exit(parent_pid);
    }
    let bridge_host = normalize_loopback_bridge_host(&args.bridge_host)?;
    let ports = parse_bridge_ports(&args.bridge_ports)?;
    let (bridge, listen_metrics) = BridgeServer::listen_with_initial_wait(
        &bridge_host,
        &ports,
        args.bridge_wait_seconds,
        editor_stdio,
    )?;
    let bridge = Arc::new(bridge);
    spawn_daemon_control_server(
        bridge_host.clone(),
        args.control_port,
        bridge.clone(),
        args.bridge_wait_seconds,
    );
    write_daemon_discovery_file(&bridge_host, args.control_port, &ports);

    println!(
        "[renium] daemon ready: channels={}/{}, bind_ms={:.1}, warmup_handshake_ms={:.1}",
        bridge.channel_count(),
        bridge.expected_channel_count(),
        listen_metrics.bind_ms,
        listen_metrics.wait_for_channels_ms
    );
    println!(
        "__ROBLOX_SYNC_DAEMON_READY__ {}",
        json!({
            "ok": true,
            "channels": bridge.channel_count(),
            "expectedChannels": bridge.expected_channel_count(),
            "bindMs": listen_metrics.bind_ms,
            "warmupHandshakeMs": listen_metrics.wait_for_channels_ms,
            "serve": !editor_stdio,
        })
    );
    if editor_stdio {
        println!(
            "[renium] editor-owned stdio mode: serving JSON requests from stdin; exits when stdin closes"
        );
    }
    let _ = io::stdout().flush();

    let stdin = io::stdin();
    let mut stdin = stdin.lock();
    let mut line = String::new();
    let mut shutdown_requested = false;
    loop {
        match read_bounded_line(&mut stdin, &mut line, MAX_DAEMON_LINE_BYTES)
            .context("Failed to read daemon request from stdin")?
        {
            BoundedLineRead::Eof => break,
            BoundedLineRead::Line => {}
            BoundedLineRead::TooLong => {
                println!(
                    "__ROBLOX_SYNC_DAEMON_RESULT__ {}",
                    json!({
                        "id": 0,
                        "ok": false,
                        "code": 1,
                        "error": format!("Daemon request exceeds {MAX_DAEMON_LINE_BYTES} bytes"),
                    })
                );
                let _ = io::stdout().flush();
                continue;
            }
        }
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        let request_started = Instant::now();
        let request: BridgeDaemonRequest = match serde_json::from_str(trimmed) {
            Ok(request) => request,
            Err(err) => {
                println!(
                    "__ROBLOX_SYNC_DAEMON_RESULT__ {}",
                    json!({
                        "id": 0,
                        "ok": false,
                        "code": 1,
                        "error": format!("Invalid daemon request JSON: {err}"),
                        "elapsedMs": elapsed_ms(request_started),
                    })
                );
                let _ = io::stdout().flush();
                continue;
            }
        };
        if let Err(err) = validate_daemon_request(&request) {
            println!(
                "__ROBLOX_SYNC_DAEMON_RESULT__ {}",
                json!({
                    "id": request.id,
                    "ok": false,
                    "code": 1,
                    "error": format!("Invalid daemon request: {err:#}"),
                    "elapsedMs": elapsed_ms(request_started),
                })
            );
            let _ = io::stdout().flush();
            continue;
        }

        if request.command == "shutdown" {
            shutdown_requested = true;
            println!(
                "__ROBLOX_SYNC_DAEMON_RESULT__ {}",
                json!({
                    "id": request.id,
                    "ok": true,
                    "code": 0,
                    "elapsedMs": elapsed_ms(request_started),
                })
            );
            let _ = io::stdout().flush();
            break;
        }

        let result = (|| -> Result<()> {
            let _request_gate = bridge.acquire_request_gate(DAEMON_CONTROL_QUEUE_TIMEOUT)?;
            bridge.clear_runtime_pins();
            set_place_filter(request.place.clone());
            let daemon_command = normalize_daemon_command(&request.command)
                .with_context(|| format!("Unsupported daemon command: {}", request.command))?;

            let target = match daemon_command {
                "studio-device" => BridgeTarget::Edit,
                "execute-luau"
                    if request
                        .args
                        .iter()
                        .any(|arg| arg == "-c" || arg == "--client" || arg == "--player") =>
                {
                    BridgeTarget::Client
                }
                "get-console-output"
                    if request
                        .args
                        .iter()
                        .any(|arg| arg == "--client" || arg == "--player") =>
                {
                    BridgeTarget::Client
                }
                "press" | "click" | "key" | "ui" | "type" | "goto" => BridgeTarget::Client,
                "shot"
                    if request
                        .args
                        .iter()
                        .any(|arg| arg == "-p" || arg == "--player" || arg == "--client") =>
                {
                    BridgeTarget::Client
                }
                "shot" if request.args.iter().any(|arg| arg == "--studio") => BridgeTarget::Edit,
                "shot" => BridgeTarget::Main,
                "wait-until"
                    if request
                        .args
                        .iter()
                        .any(|arg| arg == "-c" || arg == "--client" || arg == "--player") =>
                {
                    BridgeTarget::Client
                }
                _ => BridgeTarget::Main,
            };
            let required_channels = bridge.expected_channel_count();
            if daemon_command == "wait-for-channels" {
                wait_for_daemon_bridge_channels(
                    &bridge,
                    args.bridge_wait_seconds,
                    BridgeTarget::Main,
                )?;
                return Ok(());
            }
            if daemon_command == "list-clients" {
                println!(
                    "{}",
                    serde_json::to_string_pretty(
                        &json!({ "clients": bridge.list_bridge_clients() })
                    )?
                );
                return Ok(());
            }

            let ready_channels = bridge.wait_for_ready_channels_for_target(
                required_channels,
                Duration::from_secs_f64(args.bridge_wait_seconds.max(1.0)),
                target,
            );
            if ready_channels < required_channels {
                bail!(
                    "Only {}/{} persistent {} plugin bridge channels are ready{}. Missing ports: {:?}",
                    ready_channels,
                    required_channels,
                    BridgeServer::target_label(target),
                    place_filter()
                        .map(|place| format!(" for place filter '{place}'"))
                        .unwrap_or_default(),
                    bridge.missing_ports_for_target(target)
                );
            }

            let bridge_info = bridge.cached_bridge_info_for_target(target)?;
            validate_bridge_info(&bridge_info)?;
            let bridge_info_refresh_ms = 0.0;

            match daemon_command {
                "review-decision" => {
                    let review_args: EditorReviewDecisionArgs =
                        parse_daemon_request_args("editor-review-decision", &request.args)?;
                    let result = editor_review_decision_result(&review_args, &bridge)?;
                    println!("{}", serde_json::to_string_pretty(&result)?);
                    Ok(())
                }
                "export-snapshots" => {
                    let export_args: ExportSnapshotsArgs =
                        parse_daemon_request_args("export-snapshots", &request.args)?;
                    export_snapshots_with_warm_bridge(
                        export_args,
                        &bridge,
                        &bridge_info,
                        bridge_info_refresh_ms,
                        false,
                    )
                }
                "push-editor-changes" => {
                    let push_args: PushEditorChangesArgs =
                        parse_daemon_request_args("push-editor-changes", &request.args)?;
                    push_editor_changes_with_warm_bridge(push_args, &bridge).map(|_| ())
                }
                "apply-editor-property" => {
                    let property_args: ApplyEditorPropertyArgs =
                        parse_daemon_request_args("apply-editor-property", &request.args)?;
                    apply_editor_property_with_warm_bridge(property_args, &bridge)
                }
                "apply-editor-delete" => {
                    let delete_args: ApplyEditorDeleteArgs =
                        parse_daemon_request_args("apply-editor-delete", &request.args)?;
                    apply_editor_delete_with_warm_bridge(delete_args, &bridge)
                }
                "get-console-output" => {
                    let console_args: PluginConsoleOutputArgs =
                        parse_daemon_request_args("get-console-output", &request.args)?;
                    get_console_output_with_warm_bridge(console_args, &bridge)
                }
                "execute-luau" => {
                    let luau_args: ExecuteLuauArgs =
                        parse_daemon_request_args("execute-luau", &request.args)?;
                    execute_luau_with_warm_bridge(luau_args, &bridge)
                }
                "studio-device" => {
                    let device_args: StudioDeviceArgs =
                        parse_daemon_request_args("studio-device", &request.args)?;
                    let result = studio_device_result(&device_args, &bridge)?;
                    println!("{}", serde_json::to_string_pretty(&result)?);
                    Ok(())
                }
                "start-stop-play" => {
                    let play_args: StartStopPlayArgs =
                        parse_daemon_request_args("start-stop-play", &request.args)?;
                    start_stop_play_with_warm_bridge(play_args, &bridge)
                }
                "studio-change-state" => {
                    let state_args: StudioChangeStateArgs =
                        parse_daemon_request_args("studio-change-state", &request.args)?;
                    studio_change_state_with_warm_bridge(state_args, &bridge)
                }
                "press" => {
                    let press_args: PressArgs = parse_daemon_request_args("press", &request.args)?;
                    let result = press_result(&press_args, &bridge)?;
                    println!("{}", serde_json::to_string_pretty(&result)?);
                    Ok(())
                }
                "click" => {
                    let click_args: ClickArgs = parse_daemon_request_args("click", &request.args)?;
                    let result = click_result(&click_args, &bridge)?;
                    println!("{}", serde_json::to_string_pretty(&result)?);
                    Ok(())
                }
                "key" => {
                    let key_args: KeyArgs = parse_daemon_request_args("key", &request.args)?;
                    let result = key_result(&key_args, &bridge)?;
                    println!("{}", serde_json::to_string_pretty(&result)?);
                    Ok(())
                }
                "ui" => {
                    let ui_args: UiArgs = parse_daemon_request_args("ui", &request.args)?;
                    let result = ui_result(&ui_args, &bridge)?;
                    println!("{}", serde_json::to_string(&result)?);
                    Ok(())
                }
                "type" => {
                    let type_args: TypeArgs = parse_daemon_request_args("type", &request.args)?;
                    let result = type_result(&type_args, &bridge)?;
                    println!("{}", serde_json::to_string_pretty(&result)?);
                    Ok(())
                }
                "wait-until" => {
                    let wait_args: WaitUntilArgs =
                        parse_daemon_request_args("wait-until", &request.args)?;
                    let result = wait_until_result(&wait_args, &bridge)?;
                    println!("{}", serde_json::to_string_pretty(&result)?);
                    Ok(())
                }
                "shot" => {
                    let shot_args: ShotArgs = parse_daemon_request_args("shot", &request.args)?;
                    let result = shot_result(&shot_args, &bridge)?;
                    println!("{}", serde_json::to_string_pretty(&result)?);
                    Ok(())
                }
                "goto" => {
                    let goto_args: GotoArgs = parse_daemon_request_args("goto", &request.args)?;
                    let result = goto_result(&goto_args, &bridge)?;
                    println!("{}", serde_json::to_string_pretty(&result)?);
                    Ok(())
                }
                other => bail!("Unsupported daemon command: {other}"),
            }
        })();

        let elapsed = elapsed_ms(request_started);
        match result {
            Ok(()) => {
                println!(
                    "[renium] daemon request done: id={}, command={}, elapsed_ms={:.1}",
                    request.id, request.command, elapsed
                );
                println!(
                    "__ROBLOX_SYNC_DAEMON_RESULT__ {}",
                    json!({
                        "id": request.id,
                        "ok": true,
                        "code": 0,
                        "elapsedMs": elapsed,
                    })
                );
            }
            Err(err) => {
                eprintln!(
                    "[renium] daemon request failed: id={}, command={}, elapsed_ms={:.1},  error={:#}",
                    request.id, request.command, elapsed, err
                );
                println!(
                    "__ROBLOX_SYNC_DAEMON_RESULT__ {}",
                    json!({
                        "id": request.id,
                        "ok": false,
                        "code": 1,
                        "error": format!("{:#}", err),
                        "elapsedMs": elapsed,
                    })
                );
            }
        }
        let _ = io::stdout().flush();
    }

    while !editor_stdio && !shutdown_requested && bridge.alive.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_millis(250));
    }
    bridge.alive.store(false, Ordering::Relaxed);
    if editor_stdio && !shutdown_requested {
        println!("[renium] stdin closed; editor-owned daemon exiting");
    } else {
        println!("[renium] daemon stopped");
    }
    Ok(())
}

fn spawn_daemon_control_server(
    host: String,
    port: u16,
    bridge: Arc<BridgeServer>,
    bridge_wait_seconds: f64,
) {
    let bind_host = match normalize_loopback_bridge_host(&host) {
        Ok(host) => host,
        Err(err) => {
            eprintln!("[renium] warning: daemon control disabled: {err:#}");
            return;
        }
    };
    let listener = match TcpListener::bind((bind_host.as_str(), port)) {
        Ok(listener) => listener,
        Err(err) => {
            println!(
                "[renium] warning: daemon control unavailable on {}:{}: {}",
                bind_host, port, err
            );
            return;
        }
    };
    println!(
        "[renium] daemon control listening on {}:{}",
        bind_host, port
    );
    let active_connections = Arc::new(AtomicUsize::new(0));
    thread::spawn(move || {
        while bridge.alive.load(Ordering::Relaxed) {
            match listener.accept() {
                Ok((stream, _addr)) => {
                    let previous = active_connections.fetch_add(1, Ordering::Relaxed);
                    if previous >= MAX_DAEMON_CONTROL_CONNECTIONS {
                        active_connections.fetch_sub(1, Ordering::Relaxed);
                        eprintln!(
                            "[renium] warning: rejecting daemon control connection; {} connection limit reached",
                            MAX_DAEMON_CONTROL_CONNECTIONS
                        );
                        continue;
                    }
                    let _ = stream.set_nonblocking(false);
                    let bridge = bridge.clone();
                    let active_connections = active_connections.clone();
                    thread::spawn(move || {
                        let result =
                            handle_daemon_control_connection(stream, &bridge, bridge_wait_seconds);
                        active_connections.fetch_sub(1, Ordering::Relaxed);
                        if let Err(err) = result {
                            eprintln!("[renium] daemon control error: {err:#}");
                        }
                    });
                }
                Err(err) => {
                    if bridge.alive.load(Ordering::Relaxed) {
                        println!("[renium] warning: daemon control accept failed: {err}");
                        thread::sleep(Duration::from_millis(25));
                    }
                }
            }
        }
    });
}

fn handle_daemon_control_connection(
    stream: TcpStream,
    bridge: &BridgeServer,
    bridge_wait_seconds: f64,
) -> Result<()> {
    let _ = stream.set_read_timeout(Some(DAEMON_CONTROL_IDLE_TIMEOUT));
    let _ = stream.set_write_timeout(Some(DAEMON_CONTROL_IDLE_TIMEOUT));
    let reader_stream = stream
        .try_clone()
        .context("Failed to clone control stream")?;
    let mut reader = BufReader::new(reader_stream);
    let mut writer = BufWriter::new(stream);
    let mut line = String::new();
    loop {
        match read_bounded_line(&mut reader, &mut line, MAX_DAEMON_LINE_BYTES)
            .context("Failed to read daemon control request")?
        {
            BoundedLineRead::Eof => break,
            BoundedLineRead::Line => {}
            BoundedLineRead::TooLong => {
                writeln!(
                    writer,
                    "{}",
                    serde_json::to_string(&json!({
                        "id": 0,
                        "ok": false,
                        "code": 1,
                        "error": format!("Daemon request exceeds {MAX_DAEMON_LINE_BYTES} bytes"),
                    }))?
                )?;
                writer.flush()?;
                continue;
            }
        }
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let request_started = Instant::now();
        let response = match serde_json::from_str::<BridgeDaemonRequest>(trimmed) {
            Ok(request) => {
                match validate_daemon_request(&request).and_then(|()| {
                    if normalize_daemon_command(&request.command) == Some("review-decision") {
                        if request.place.is_some() {
                            set_place_filter(request.place.clone());
                        }
                        return handle_daemon_control_request(
                            &request,
                            bridge,
                            bridge_wait_seconds,
                        );
                    }
                    let _request_gate =
                        bridge.acquire_request_gate(DAEMON_CONTROL_QUEUE_TIMEOUT)?;
                    bridge.clear_runtime_pins();
                    set_place_filter(request.place.clone());
                    handle_daemon_control_request(&request, bridge, bridge_wait_seconds)
                }) {
                    Ok(result) => json!({
                        "id": request.id,
                        "ok": true,
                        "code": 0,
                        "elapsedMs": elapsed_ms(request_started),
                        "result": result,
                    }),
                    Err(err) => json!({
                        "id": request.id,
                        "ok": false,
                        "code": 1,
                        "elapsedMs": elapsed_ms(request_started),
                        "error": format!("{:#}", err),
                    }),
                }
            }
            Err(err) => json!({
                "id": 0,
                "ok": false,
                "code": 1,
                "elapsedMs": elapsed_ms(request_started),
                "error": format!("Invalid daemon control request JSON: {err}"),
            }),
        };
        writeln!(writer, "{}", serde_json::to_string(&response)?)?;
        writer.flush()?;
    }
    Ok(())
}

fn handle_daemon_control_request(
    request: &BridgeDaemonRequest,
    bridge: &BridgeServer,
    bridge_wait_seconds: f64,
) -> Result<Value> {
    let daemon_command = normalize_daemon_command(&request.command)
        .with_context(|| format!("Unsupported daemon command: {}", request.command))?;

    if daemon_command == "wait-for-channels" {
        wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
        return Ok(json!({
            "ok": true,
            "channels": bridge.channel_count(),
            "expectedChannels": bridge.expected_channel_count(),
        }));
    }

    if daemon_command == "list-clients" {
        return Ok(json!({
            "ok": true,
            "clients": bridge.list_bridge_clients(),
            "expectedChannels": bridge.expected_channel_count(),
        }));
    }

    if daemon_command == "review-decision" {
        wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
        let review_args: EditorReviewDecisionArgs =
            parse_daemon_request_args("editor-review-decision", &request.args)?;
        return editor_review_decision_result(&review_args, bridge);
    }

    match daemon_command {
        "export-snapshots" => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
            let bridge_info = bridge.cached_bridge_info_for_target(BridgeTarget::Main)?;
            let export_args: ExportSnapshotsArgs =
                parse_daemon_request_args("export-snapshots", &request.args)?;
            export_snapshots_with_warm_bridge(export_args, bridge, &bridge_info, 0.0, false)?;
            Ok(json!({ "ok": true }))
        }
        "push-editor-changes" => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
            let push_args: PushEditorChangesArgs =
                parse_daemon_request_args("push-editor-changes", &request.args)?;
            let mut summary = push_editor_changes_with_warm_bridge(push_args, bridge)?;
            summary.entry("ok".to_string()).or_insert(Value::Bool(true));
            Ok(Value::Object(summary))
        }
        "apply-editor-property" => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
            let property_args: ApplyEditorPropertyArgs =
                parse_daemon_request_args("apply-editor-property", &request.args)?;
            apply_editor_property_with_warm_bridge(property_args, bridge)?;
            Ok(json!({ "ok": true }))
        }
        "apply-editor-delete" => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
            let delete_args: ApplyEditorDeleteArgs =
                parse_daemon_request_args("apply-editor-delete", &request.args)?;
            apply_editor_delete_with_warm_bridge(delete_args, bridge)?;
            Ok(json!({ "ok": true }))
        }
        "get-console-output" => {
            let console_args: PluginConsoleOutputArgs =
                parse_daemon_request_args("get-console-output", &request.args)?;
            let target = if console_args.client || console_args.player.is_some() {
                BridgeTarget::Client
            } else {
                BridgeTarget::Main
            };
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, target)?;
            get_console_output_result(console_args, bridge)
        }
        "execute-luau" => {
            let luau_args: ExecuteLuauArgs =
                parse_daemon_request_args("execute-luau", &request.args)?;
            let target = if luau_args.client || luau_args.player.is_some() {
                BridgeTarget::Client
            } else {
                BridgeTarget::Main
            };
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, target)?;
            execute_luau_result(luau_args, bridge)
        }
        "studio-device" => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Edit)?;
            let device_args: StudioDeviceArgs =
                parse_daemon_request_args("studio-device", &request.args)?;
            studio_device_result(&device_args, bridge)
        }
        "start-stop-play" => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
            let play_args: StartStopPlayArgs =
                parse_daemon_request_args("start-stop-play", &request.args)?;
            start_stop_play_result(play_args, bridge)
        }
        "studio-change-state" => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
            let state_args: StudioChangeStateArgs =
                parse_daemon_request_args("studio-change-state", &request.args)?;
            studio_change_state_result(state_args, bridge)
        }
        "press" => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Client)?;
            let press_args: PressArgs = parse_daemon_request_args("press", &request.args)?;
            press_result(&press_args, bridge)
        }
        "click" => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Client)?;
            let click_args: ClickArgs = parse_daemon_request_args("click", &request.args)?;
            click_result(&click_args, bridge)
        }
        "key" => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Client)?;
            let key_args: KeyArgs = parse_daemon_request_args("key", &request.args)?;
            key_result(&key_args, bridge)
        }
        "ui" => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Client)?;
            let ui_args: UiArgs = parse_daemon_request_args("ui", &request.args)?;
            ui_result(&ui_args, bridge)
        }
        "type" => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Client)?;
            let type_args: TypeArgs = parse_daemon_request_args("type", &request.args)?;
            type_result(&type_args, bridge)
        }
        "wait-until" => {
            let wait_args: WaitUntilArgs = parse_daemon_request_args("wait-until", &request.args)?;
            let target = if wait_args.client || wait_args.player.is_some() {
                BridgeTarget::Client
            } else {
                BridgeTarget::Main
            };
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, target)?;
            wait_until_result(&wait_args, bridge)
        }
        "shot" => {
            let shot_args: ShotArgs = parse_daemon_request_args("shot", &request.args)?;
            let target = if shot_args.studio {
                BridgeTarget::Edit
            } else if shot_args.client || shot_args.player.is_some() {
                BridgeTarget::Client
            } else {
                BridgeTarget::Main
            };
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, target)?;
            shot_result(&shot_args, bridge)
        }
        "goto" => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Client)?;
            let goto_args: GotoArgs = parse_daemon_request_args("goto", &request.args)?;
            goto_result(&goto_args, bridge)
        }
        other => bail!("Daemon control does not support command: {other}"),
    }
}

fn wait_for_daemon_bridge_channels(
    bridge: &BridgeServer,
    bridge_wait_seconds: f64,
    target: BridgeTarget,
) -> Result<()> {
    let required_channels = bridge.expected_channel_count();
    let ready_channels = bridge.wait_for_ready_channels_for_target(
        required_channels,
        Duration::from_secs_f64(bridge_wait_seconds.max(1.0)),
        target,
    );
    if ready_channels < required_channels {
        bail!(
            "Only {}/{} persistent {} plugin bridge channels are ready{}. Missing ports: {:?}",
            ready_channels,
            required_channels,
            BridgeServer::target_label(target),
            place_filter()
                .map(|place| format!(" for place filter '{place}'"))
                .unwrap_or_default(),
            bridge.missing_ports_for_target(target)
        );
    }
    let bridge_info = bridge.cached_bridge_info_for_target(target)?;
    validate_bridge_info(&bridge_info)?;
    Ok(())
}

fn normalize_daemon_command(command: &str) -> Option<&'static str> {
    match command {
        "" | "x" | "export" | "export-snapshots" => Some("export-snapshots"),
        "push" | "push-editor-changes" => Some("push-editor-changes"),
        "prop" | "apply-editor-property" => Some("apply-editor-property"),
        "del" | "apply-editor-delete" => Some("apply-editor-delete"),
        "co" | "console" | "get-console-output" => Some("get-console-output"),
        "lx" | "luau" | "execute-luau" => Some("execute-luau"),
        "device" | "dev" | "studio-device" => Some("studio-device"),
        "play" | "start-stop-play" => Some("start-stop-play"),
        "clients" | "list-clients" => Some("list-clients"),
        "review" | "editor-review-decision" => Some("review-decision"),
        "press" => Some("press"),
        "click" => Some("click"),
        "key" => Some("key"),
        "ui" => Some("ui"),
        "type" => Some("type"),
        "wait-until" => Some("wait-until"),
        "goto" => Some("goto"),
        "shot" => Some("shot"),
        "st" | "studio" | "studio-change-state" => Some("studio-change-state"),
        "wait" | "wait-for-channels" => Some("wait-for-channels"),
        "shutdown" => Some("shutdown"),
        _ => None,
    }
}

fn bridge_get_source(args: BridgeGetSourceArgs) -> Result<()> {
    let ports = parse_bridge_ports(&args.bridge_ports)?;
    let (bridge, listen_metrics) =
        BridgeServer::listen(&args.bridge_host, &ports, args.bridge_wait_seconds)?;
    let source = bridge_fetch_source(
        &bridge,
        &args.service,
        &args.source_key,
        clamp_bridge_chunk_size(args.chunk_size),
    )?;
    let expected = match &args.expect_file {
        Some(path) => Some(
            fs::read_to_string(path)
                .with_context(|| format!("Failed to read expected file {}", path.display()))?,
        ),
        None => None,
    };
    let matches_expected = expected.as_ref().is_none_or(|expected| expected == &source);
    let summary = json!({
        "ok": matches_expected,
        "service": args.service,
        "sourceKey": args.source_key,
        "sourceLen": source.len(),
        "sourceHash": fnv1a64_hex(source.as_bytes()),
        "expectedLen": expected.as_ref().map(String::len),
        "expectedHash": expected.as_ref().map(|value| fnv1a64_hex(value.as_bytes())),
        "matchesExpected": matches_expected,
        "channels": bridge.channel_count(),
        "handshakeMs": listen_metrics.wait_for_channels_ms,
    });
    println!("__ROBLOX_SYNC_BRIDGE_SOURCE_RESULT__ {summary}");
    if !matches_expected {
        bail!("Studio source did not match expected file");
    }
    Ok(())
}

fn bridge_fetch_source(
    bridge: &BridgeServer,
    service: &str,
    source_key: &str,
    chunk_size: usize,
) -> Result<String> {
    let (source, _) = fetch_text_chunks(chunk_size, |start_index, max_len| {
        bridge.call_chunk(
            "getSourceChunk",
            json!({
                "service": service,
                "instancePath": source_key,
                "startIndex": start_index,
                "maxLen": max_len,
            }),
        )
    })?;
    Ok(source)
}

fn write_daemon_discovery_file(host: &str, control_port: u16, bridge_ports: &[u16]) {
    let bind_host = match normalize_loopback_bridge_host(host) {
        Ok(host) => host,
        Err(err) => {
            eprintln!("[renium] warning: not writing unsafe daemon discovery: {err:#}");
            return;
        }
    };
    let payload = json!({
        "schemaVersion": 1,
        "host": bind_host,
        "controlPort": control_port,
        "bridgePorts": bridge_ports,
        "pid": std::process::id(),
        "updatedUnixMs": current_millis(),
    });
    if let Ok(text) = serde_json::to_string_pretty(&payload) {
        for path in daemon_discovery_paths() {
            if let Err(err) = write_daemon_discovery_path(&path, &text) {
                eprintln!(
                    "[renium] warning: failed to update daemon discovery {}: {err}",
                    path.display()
                );
            }
        }
    }
}

fn write_daemon_discovery_path(path: &Path, text: &str) -> io::Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    let nonce = current_millis();
    let file_name = path
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("daemon");
    let temporary =
        path.with_file_name(format!(".{file_name}.{}.{}.tmp", std::process::id(), nonce));
    let mut file = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&temporary)?;
    file.write_all(text.as_bytes())?;
    file.write_all(b"\n")?;
    file.sync_all()?;
    drop(file);

    if let Err(first_error) = fs::rename(&temporary, path) {
        if path.exists() {
            fs::remove_file(path)?;
            fs::rename(&temporary, path)?;
        } else {
            let _ = fs::remove_file(&temporary);
            return Err(first_error);
        }
    }
    Ok(())
}

fn daemon_control_endpoints() -> Vec<std::net::SocketAddr> {
    let mut out = Vec::new();
    let mut seen = HashSet::new();

    if let Ok(raw) = std::env::var("RENIUM_DAEMON") {
        push_daemon_endpoint(&mut out, &mut seen, raw.trim());
    }

    let env_host = std::env::var("RENIUM_DAEMON_HOST").unwrap_or_else(|_| "127.0.0.1".to_string());
    if let Ok(raw_port) = std::env::var("RENIUM_DAEMON_CONTROL_PORT")
        && let Ok(port) = raw_port.trim().parse::<u16>()
    {
        push_daemon_endpoint(
            &mut out,
            &mut seen,
            &loopback_host_port(env_host.trim(), port),
        );
    }

    for path in daemon_discovery_paths() {
        if let Ok(text) = fs::read_to_string(&path)
            && let Ok(value) = serde_json::from_str::<Value>(&text)
            && let Some(endpoint) = daemon_discovery_endpoint(&value)
        {
            let key = endpoint.to_string();
            if seen.insert(key) {
                out.push(endpoint);
            }
        }
    }

    push_daemon_endpoint(
        &mut out,
        &mut seen,
        &loopback_host_port("127.0.0.1", DEFAULT_DAEMON_CONTROL_PORT),
    );
    out
}

fn daemon_discovery_paths() -> Vec<PathBuf> {
    let mut paths = Vec::new();
    if let Ok(path) = std::env::var("RENIUM_DAEMON_FILE") {
        let path = path.trim();
        if !path.is_empty() {
            paths.push(PathBuf::from(path));
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        paths.push(cwd.join(DAEMON_DISCOVERY_FILE));
    }
    if let Some(path) = local_app_data_daemon_path() {
        paths.push(path);
    }
    paths
}

fn local_app_data_daemon_path() -> Option<PathBuf> {
    if let Some(base) = std::env::var_os("LOCALAPPDATA") {
        return Some(PathBuf::from(base).join("Renium").join("daemon.json"));
    }
    let home = std::env::var_os("HOME")?;
    Some(PathBuf::from(home).join(".renium").join("daemon.json"))
}

fn daemon_discovery_endpoint(value: &Value) -> Option<std::net::SocketAddr> {
    let schema_version = value.get("schemaVersion").and_then(Value::as_u64);
    if schema_version.is_some_and(|version| version != 1) {
        return None;
    }
    let host = normalize_loopback_bridge_host(value.get("host")?.as_str()?).ok()?;
    let port = value
        .get("controlPort")
        .and_then(Value::as_u64)
        .and_then(|value| u16::try_from(value).ok())?;
    if port == 0 {
        return None;
    }
    let pid = value
        .get("pid")
        .and_then(Value::as_u64)
        .and_then(|value| u32::try_from(value).ok())?;
    let updated_ms = value.get("updatedUnixMs").and_then(Value::as_u64)? as u128;
    let now = current_millis();
    if updated_ms > now.saturating_add(DAEMON_DISCOVERY_MAX_FUTURE_SKEW_MS)
        || now.saturating_sub(updated_ms) > DAEMON_DISCOVERY_MAX_AGE_MS
        || !is_process_alive(pid)
    {
        return None;
    }
    loopback_host_port(&host, port)
        .to_socket_addrs()
        .ok()?
        .find(is_loopback_endpoint)
}

fn is_process_alive(pid: u32) -> bool {
    if pid == 0 {
        return false;
    }
    #[cfg(windows)]
    unsafe {
        use windows_sys::Win32::Foundation::CloseHandle;
        use windows_sys::Win32::System::Threading::{
            OpenProcess, PROCESS_SYNCHRONIZE, WaitForSingleObject,
        };

        let handle = OpenProcess(PROCESS_SYNCHRONIZE, 0, pid);
        if handle.is_null() {
            return false;
        }
        let alive = WaitForSingleObject(handle, 0) == 0x0000_0102;
        CloseHandle(handle);
        alive
    }
    #[cfg(not(windows))]
    {
        unsafe {
            libc::kill(pid as libc::pid_t, 0) == 0
                || io::Error::last_os_error().raw_os_error() == Some(libc::EPERM)
        }
    }
}

fn push_daemon_endpoint(
    out: &mut Vec<std::net::SocketAddr>,
    seen: &mut HashSet<String>,
    raw: &str,
) {
    let text = raw.trim();
    if text.is_empty() {
        return;
    }
    if let Ok(address) = text.parse::<std::net::SocketAddr>() {
        if !is_loopback_endpoint(&address) {
            return;
        }
        let key = address.to_string();
        if seen.insert(key) {
            out.push(address);
        }
        return;
    }
    if let Ok(addresses) = text.to_socket_addrs() {
        for address in addresses {
            if !is_loopback_endpoint(&address) {
                continue;
            }
            let key = address.to_string();
            if seen.insert(key) {
                out.push(address);
            }
        }
    }
}

fn try_daemon_control_request(command: &str, args: Vec<String>) -> Result<Option<Value>> {
    let mut stream = None;
    for address in daemon_control_endpoints() {
        match TcpStream::connect_timeout(&address, DAEMON_CONTROL_CONNECT_TIMEOUT) {
            Ok(value) => {
                stream = Some(value);
                break;
            }
            Err(_) => continue,
        }
    }
    let Some(mut stream) = stream else {
        return Ok(None);
    };
    let _ = stream.set_read_timeout(Some(DAEMON_CONTROL_RESPONSE_TIMEOUT));
    let _ = stream.set_write_timeout(Some(DAEMON_CONTROL_IDLE_TIMEOUT));
    let request = BridgeDaemonRequest {
        id: current_millis().min(u128::from(u64::MAX)) as u64,
        command: command.to_string(),
        args,
        place: place_filter(),
    };
    validate_daemon_request(&request)?;
    writeln!(stream, "{}", serde_json::to_string(&request)?)?;
    stream.flush()?;

    let mut reader = BufReader::new(stream);
    let mut line = String::new();
    match read_bounded_line(&mut reader, &mut line, MAX_DAEMON_LINE_BYTES) {
        Ok(BoundedLineRead::Line) => {}
        Ok(BoundedLineRead::Eof) => {
            bail!("Renium daemon closed the control connection before responding")
        }
        Ok(BoundedLineRead::TooLong) => bail!("Daemon control response exceeds safe size limit"),
        Err(err) => {
            return Err(err).with_context(|| {
                format!("Renium daemon did not finish {command} before the control timeout")
            });
        }
    }
    let response: Value =
        serde_json::from_str(line.trim()).context("Invalid daemon control response")?;
    if response.get("ok").and_then(Value::as_bool) == Some(false) {
        let message = response
            .get("error")
            .and_then(Value::as_str)
            .unwrap_or("Daemon control request failed");
        bail!("{message}");
    }
    Ok(Some(
        response
            .get("result")
            .cloned()
            .unwrap_or_else(|| response.clone()),
    ))
}

fn get_console_output_daemon_args(args: &PluginConsoleOutputArgs) -> Vec<String> {
    let mut out = vec![
        "-n".to_string(),
        args.limit.to_string(),
        "-s".to_string(),
        args.since_seq.to_string(),
    ];
    if args.clear {
        out.push("-c".to_string());
    }
    if args.client {
        out.push("--client".to_string());
    }
    if let Some(player) = args.player.as_ref() {
        out.push("--player".to_string());
        out.push(player.clone());
    }
    out
}

fn execute_luau_daemon_args(args: &ExecuteLuauArgs) -> Result<Vec<String>> {
    let mut out = vec!["-t".to_string(), args.timeout.to_string()];
    if args.client {
        out.push("-c".to_string());
    }
    if let Some(player) = args.player.as_ref() {
        out.push("--player".to_string());
        out.push(player.clone());
    }
    if let Some(code) = args.code.as_ref() {
        out.push("-e".to_string());
        out.push(code.clone());
        return Ok(out);
    }
    if let Some(path) = args.file.as_ref() {
        let path = canonical_path(path).unwrap_or_else(|_| path.clone());
        out.push("-f".to_string());
        out.push(path.display().to_string());
        return Ok(out);
    }
    Ok(out)
}

