fn json_to_rbx_color3(value: &Value) -> Option<RbxColor3> {
    let value = json_wrapped_value(value, "Color3");
    if let Some(items) = value.as_array() {
        if items.len() < 3 {
            return None;
        }
        return Some(RbxColor3::new(
            json_f32(&items[0])?,
            json_f32(&items[1])?,
            json_f32(&items[2])?,
        ));
    }
    let obj = json_object(value)?;
    if obj.get("r").is_none()
        && obj.get("g").is_none()
        && obj.get("b").is_none()
        && let Some(nested) = obj.get("value").or_else(|| obj.get("color"))
    {
        return json_to_rbx_color3(nested);
    }
    if obj.get("_type").and_then(Value::as_str) == Some("Color3uint8") {
        return Some(RbxColor3::from(RbxColor3uint8::new(
            json_u8(obj.get("r")?)?,
            json_u8(obj.get("g")?)?,
            json_u8(obj.get("b")?)?,
        )));
    }
    Some(RbxColor3::new(
        json_f32(obj.get("r")?)?,
        json_f32(obj.get("g")?)?,
        json_f32(obj.get("b")?)?,
    ))
}

fn json_to_rbx_brick_color(value: &Value) -> Option<RbxBrickColor> {
    let number = json_object(value)
        .and_then(|obj| obj.get("number"))
        .and_then(json_i64)
        .or_else(|| json_i64(value))?;
    let number = u16::try_from(number).ok()?;
    RbxBrickColor::from_number(number)
}

fn json_to_rbx_cframe(value: &Value) -> Option<RbxCFrame> {
    let components = json_object(value)?.get("components")?.as_array()?;
    if components.len() != 12 {
        return None;
    }
    let numbers = components
        .iter()
        .map(json_f32)
        .collect::<Option<Vec<_>>>()?;
    Some(RbxCFrame::new(
        RbxVector3::new(numbers[0], numbers[1], numbers[2]),
        RbxMatrix3::new(
            RbxVector3::new(numbers[3], numbers[4], numbers[5]),
            RbxVector3::new(numbers[6], numbers[7], numbers[8]),
            RbxVector3::new(numbers[9], numbers[10], numbers[11]),
        ),
    ))
}

fn json_to_rbx_rect(value: &Value) -> Option<RbxRect> {
    let obj = json_object(value)?;
    Some(RbxRect::new(
        RbxVector2::new(json_f32(obj.get("minX")?)?, json_f32(obj.get("minY")?)?),
        RbxVector2::new(json_f32(obj.get("maxX")?)?, json_f32(obj.get("maxY")?)?),
    ))
}

fn json_to_rbx_number_range(value: &Value) -> Option<RbxNumberRange> {
    let obj = json_object(json_wrapped_value(value, "NumberRange"))?;
    Some(RbxNumberRange::new(
        json_f32(obj.get("min")?)?,
        json_f32(obj.get("max")?)?,
    ))
}

fn json_to_rbx_number_sequence(value: &Value) -> Option<RbxNumberSequence> {
    let keypoints = json_object(json_wrapped_value(value, "NumberSequence"))?
        .get("keypoints")?
        .as_array()?;
    let keypoints = keypoints
        .iter()
        .filter_map(|keypoint| {
            let obj = keypoint.as_object()?;
            Some(RbxNumberSequenceKeypoint::new(
                json_f32(obj.get("time")?)?,
                json_f32(obj.get("value")?)?,
                obj.get("envelope").and_then(json_f32).unwrap_or(0.0),
            ))
        })
        .collect::<Vec<_>>();
    (!keypoints.is_empty()).then_some(RbxNumberSequence { keypoints })
}

fn json_to_rbx_color_sequence(value: &Value) -> Option<RbxColorSequence> {
    let keypoints = json_object(json_wrapped_value(value, "ColorSequence"))?
        .get("keypoints")?
        .as_array()?;
    let keypoints = keypoints
        .iter()
        .filter_map(|keypoint| {
            let obj = keypoint.as_object()?;
            let color = obj.get("value").or_else(|| obj.get("color"))?;
            Some(RbxColorSequenceKeypoint::new(
                json_f32(obj.get("time")?)?,
                json_to_rbx_color3(color)?,
            ))
        })
        .collect::<Vec<_>>();
    (!keypoints.is_empty()).then_some(RbxColorSequence { keypoints })
}

fn json_to_rbx_physical_properties(value: &Value) -> Option<RbxPhysicalProperties> {
    let value = json_wrapped_value(value, "PhysicalProperties");
    if value.as_bool() == Some(false) {
        return Some(RbxPhysicalProperties::Default);
    }
    if let Some(text) = value.as_str() {
        return text
            .eq_ignore_ascii_case("Default")
            .then_some(RbxPhysicalProperties::Default);
    }

    let obj = json_object(value)?;
    if obj.get("customPhysics").and_then(Value::as_bool) == Some(false) {
        return Some(RbxPhysicalProperties::Default);
    }

    Some(RbxPhysicalProperties::Custom(
        RbxCustomPhysicalProperties::new(
            json_f32(obj.get("density")?)?,
            json_f32(obj.get("friction")?)?,
            json_f32(obj.get("elasticity")?)?,
            json_f32(obj.get("frictionWeight")?)?,
            json_f32(obj.get("elasticityWeight")?)?,
            obj.get("acousticAbsorption")
                .and_then(json_f32)
                .unwrap_or(1.0),
        ),
    ))
}

fn json_to_rbx_font(value: &Value) -> Option<RbxFont> {
    let obj = json_object(value)?;
    let family = obj
        .get("family")
        .and_then(Value::as_str)
        .unwrap_or("rbxasset://fonts/families/SourceSansPro.json");
    let weight = obj
        .get("weight")
        .and_then(font_weight_from_json)
        .unwrap_or_default();
    let style = obj
        .get("style")
        .and_then(font_style_from_json)
        .unwrap_or_default();
    let mut font = RbxFont::new(family, weight, style);
    font.cached_face_id = obj
        .get("cachedFaceId")
        .or_else(|| obj.get("cached_face_id"))
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string);
    Some(font)
}

fn font_weight_from_json(value: &Value) -> Option<RbxFontWeight> {
    if let Some(weight) = json_i64(value).and_then(|value| u16::try_from(value).ok()) {
        return RbxFontWeight::from_u16(weight);
    }
    match enum_tail(value.as_str()?).to_ascii_lowercase().as_str() {
        "thin" => RbxFontWeight::from_u16(100),
        "extralight" => RbxFontWeight::from_u16(200),
        "light" => RbxFontWeight::from_u16(300),
        "regular" => RbxFontWeight::from_u16(400),
        "medium" => RbxFontWeight::from_u16(500),
        "semibold" => RbxFontWeight::from_u16(600),
        "bold" => RbxFontWeight::from_u16(700),
        "extrabold" => RbxFontWeight::from_u16(800),
        "heavy" => RbxFontWeight::from_u16(900),
        other => other.parse::<u16>().ok().and_then(RbxFontWeight::from_u16),
    }
}

fn font_style_from_json(value: &Value) -> Option<RbxFontStyle> {
    if let Some(style) = json_i64(value).and_then(|value| u8::try_from(value).ok()) {
        return RbxFontStyle::from_u8(style);
    }
    match enum_tail(value.as_str()?).to_ascii_lowercase().as_str() {
        "normal" => RbxFontStyle::from_u8(0),
        "italic" => RbxFontStyle::from_u8(1),
        other => other.parse::<u8>().ok().and_then(RbxFontStyle::from_u8),
    }
}

fn json_to_rbx_tags(value: &Value) -> Option<RbxTags> {
    if let Some(items) = value.as_array() {
        return Some(RbxTags::from(
            items
                .iter()
                .filter_map(Value::as_str)
                .map(ToString::to_string)
                .collect::<Vec<_>>(),
        ));
    }
    value.as_str().map(|text| {
        RbxTags::from(
            text.split('\0')
                .filter(|item| !item.is_empty())
                .map(ToString::to_string)
                .collect::<Vec<_>>(),
        )
    })
}

fn json_to_rbx_content(value: &Value, refs: &BytecodeModelExportRefs) -> Option<RbxContent> {
    if value.is_null() {
        return Some(RbxContent::none());
    }
    if let Some(text) = value.as_str() {
        return if text.is_empty() || text.eq_ignore_ascii_case("None") {
            Some(RbxContent::none())
        } else {
            Some(RbxContent::from_uri(text))
        };
    }
    if let Some(object) = value.as_object() {
        if let Some(wrapped) = object.get("Content") {
            return json_to_rbx_content(wrapped, refs);
        }
        if let Some(text) = object
            .get("Uri")
            .or_else(|| object.get("uri"))
            .and_then(Value::as_str)
        {
            return Some(RbxContent::from_uri(text));
        }
        if object.get("None").and_then(Value::as_bool) == Some(true) {
            return Some(RbxContent::none());
        }
        if let Some(object_ref) = object.get("Object").or_else(|| object.get("object")) {
            return Some(RbxContent::from_referent(json_to_rbx_ref(object_ref, refs)));
        }
        if object.get("_type").and_then(Value::as_str) == Some("Ref") || object.get("Ref").is_some()
        {
            return Some(RbxContent::from_referent(json_to_rbx_ref(value, refs)));
        }
    }
    Some(RbxContent::from_referent(json_to_rbx_ref(value, refs)))
}

fn json_to_rbx_ref(value: &Value, refs: &BytecodeModelExportRefs) -> RbxRef {
    let Some(object) = value.as_object().and_then(|object| {
        if object.get("_type").and_then(Value::as_str) == Some("Ref") {
            Some(object)
        } else {
            object.get("Ref").and_then(Value::as_object)
        }
    }) else {
        return value
            .as_str()
            .and_then(|raw| raw.parse::<RbxRef>().ok())
            .unwrap_or_else(RbxRef::none);
    };

    object
        .get("instanceIndex")
        .and_then(value_to_zero_based_index)
        .and_then(|index| refs.by_index.get(&index).copied())
        .or_else(|| {
            object
                .get("pathSegments")
                .and_then(path_segments_from_value)
                .map(|segments| instance_path_key(&segments))
                .and_then(|key| refs.by_path_key.get(&key).copied())
        })
        .or_else(|| {
            object
                .get("settingsId")
                .or_else(|| object.get("instanceId"))
                .and_then(Value::as_str)
                .and_then(|settings_id| refs.by_settings_id.get(settings_id).copied())
        })
        .or_else(|| {
            object
                .get("referent")
                .or_else(|| object.get("ref"))
                .and_then(Value::as_str)
                .and_then(|raw| raw.parse::<RbxRef>().ok())
        })
        .unwrap_or_else(RbxRef::none)
}

fn json_to_rbx_enum_variant(
    value: &Value,
    enum_name: Option<&str>,
    database: &ReflectionDatabase<'_>,
) -> Option<RbxVariant> {
    let object = value.as_object();
    let enum_name = object
        .and_then(|object| object.get("enumType").and_then(Value::as_str))
        .or(enum_name)
        .map(strip_enum_prefix);
    let numeric = object
        .and_then(|object| object.get("value").or_else(|| object.get("number")))
        .and_then(json_i64)
        .or_else(|| json_i64(value))
        .and_then(|value| u32::try_from(value).ok());
    let item_name = object
        .and_then(|object| object.get("name").and_then(Value::as_str))
        .or_else(|| value.as_str())
        .map(enum_tail);
    let value = numeric.or_else(|| {
        let enum_name = enum_name?;
        let item_name = item_name?;
        enum_item_value_by_name(database, enum_name, item_name)
    })?;
    if let Some(enum_name) = enum_name {
        Some(RbxVariant::EnumItem(RbxEnumItem {
            ty: enum_name.to_string(),
            value,
        }))
    } else {
        Some(RbxVariant::Enum(RbxEnum::from_u32(value)))
    }
}

fn strip_enum_prefix(value: &str) -> &str {
    value.strip_prefix("Enum.").unwrap_or(value)
}

fn enum_tail(value: &str) -> &str {
    value.split('.').next_back().unwrap_or(value)
}

fn enum_item_value_by_name(
    database: &ReflectionDatabase<'_>,
    enum_name: &str,
    item_name: &str,
) -> Option<u32> {
    let descriptor = database.enums.get(strip_enum_prefix(enum_name))?;
    descriptor
        .items
        .get(item_name)
        .copied()
        .or_else(|| descriptor.items.get(enum_tail(item_name)).copied())
}

fn enum_item_name_by_value(
    database: &ReflectionDatabase<'_>,
    enum_name: &str,
    enum_value: u32,
) -> Option<String> {
    database
        .enums
        .get(strip_enum_prefix(enum_name))?
        .items
        .iter()
        .find_map(|(name, value)| (*value == enum_value).then(|| name.to_string()))
}

fn rbx_model_top_level_refs(dom: &RbxWeakDom) -> Vec<RbxRef> {
    if dom.root().class.as_str() == "DataModel" {
        dom.root().children().to_vec()
    } else {
        vec![dom.root_ref()]
    }
}

fn collect_rbx_subtree_preorder(dom: &RbxWeakDom, referent: RbxRef, out: &mut Vec<RbxRef>) {
    out.push(referent);
    if let Some(instance) = dom.get_by_ref(referent) {
        for child in instance.children() {
            collect_rbx_subtree_preorder(dom, *child, out);
        }
    }
}

fn settings_root_indices(document: &SettingsBytecode) -> Vec<usize> {
    document
        .instances
        .iter()
        .enumerate()
        .filter_map(|(index, instance)| instance.parent_index.is_none().then_some(index))
        .collect()
}

struct NativePropertyFilter {
    allowed: HashSet<String>,
    decode_allowed: HashSet<String>,
    renamed: HashMap<String, String>,
    output_names: HashSet<String>,
    reconstruct_decal_color_map: bool,
    reconstruct_weld_enabled: bool,
}

fn native_property_data_type_supported(data_type: &RbxDataType<'_>) -> bool {
    match data_type {
        RbxDataType::Enum(_) => true,
        RbxDataType::Value(value_type) => matches!(
            value_type,
            RbxVariantType::Bool
                | RbxVariantType::Int32
                | RbxVariantType::Int64
                | RbxVariantType::Float32
                | RbxVariantType::Float64
                | RbxVariantType::String
                | RbxVariantType::BinaryString
                | RbxVariantType::ContentId
                | RbxVariantType::Content
                | RbxVariantType::Ref
                | RbxVariantType::Vector2
                | RbxVariantType::Vector3
                | RbxVariantType::UDim
                | RbxVariantType::UDim2
                | RbxVariantType::Color3
                | RbxVariantType::Color3uint8
                | RbxVariantType::ColorSequence
                | RbxVariantType::NumberSequence
                | RbxVariantType::NumberRange
                | RbxVariantType::CFrame
                | RbxVariantType::OptionalCFrame
                | RbxVariantType::Rect
                | RbxVariantType::Font
                | RbxVariantType::BrickColor
                | RbxVariantType::PhysicalProperties
                | RbxVariantType::Axes
                | RbxVariantType::Faces
                | RbxVariantType::Ray
        ),
        _ => false,
    }
}

fn native_property_descriptor_supported(descriptor: &RbxPropertyDescriptor<'_>) -> bool {
    let RbxPropertyKind::Canonical { serialization } = &descriptor.kind else {
        return false;
    };
    if matches!(serialization, RbxPropertySerialization::DoesNotSerialize) {
        return false;
    }
    let serializes_as = matches!(serialization, RbxPropertySerialization::SerializesAs(_));
    if descriptor.tags.iter().any(|tag| {
        matches!(
            tag,
            RbxPropertyTag::Deprecated
                | RbxPropertyTag::Hidden
                | RbxPropertyTag::NotBrowsable
                | RbxPropertyTag::WriteOnly
        ) || (*tag == RbxPropertyTag::ReadOnly && !serializes_as)
    }) {
        return false;
    }
    if !matches!(
        descriptor.scriptability,
        RbxScriptability::ReadWrite | RbxScriptability::Read | RbxScriptability::Custom
    ) {
        return false;
    }
    native_property_data_type_supported(&descriptor.data_type)
}

fn rbx_reflection_class_is_a(
    database: &ReflectionDatabase<'_>,
    class_name: &str,
    target: &str,
) -> bool {
    let Some(class) = database.classes.get(class_name) else {
        return false;
    };
    database
        .superclasses_iter(class)
        .any(|descriptor| descriptor.name == target)
}

fn native_property_filter(
    database: &ReflectionDatabase<'_>,
    class_name: &str,
) -> NativePropertyFilter {
    let mut allowed = HashSet::new();
    let mut decode_allowed = HashSet::new();
    let mut renamed = HashMap::new();
    if let Some(class) = database.classes.get(class_name) {
        for descriptor in database.superclasses_iter(class) {
            for property in descriptor.properties.values() {
                if !native_property_descriptor_supported(property) {
                    continue;
                }
                match &property.kind {
                    RbxPropertyKind::Canonical {
                        serialization: RbxPropertySerialization::Migrate(migration),
                    } => {
                        decode_allowed.insert(property.name.to_string());
                        allowed.extend(
                            migration
                                .new_property_names()
                                .iter()
                                .map(|name| (*name).to_string()),
                        );
                    }
                    RbxPropertyKind::Canonical {
                        serialization: RbxPropertySerialization::SerializesAs(serialized_name),
                    } => {
                        allowed.insert(property.name.to_string());
                        allowed.insert((*serialized_name).to_string());
                        decode_allowed.insert(property.name.to_string());
                        decode_allowed.insert((*serialized_name).to_string());
                        renamed.insert((*serialized_name).to_string(), property.name.to_string());
                    }
                    RbxPropertyKind::Canonical { .. } => {
                        allowed.insert(property.name.to_string());
                        decode_allowed.insert(property.name.to_string());
                    }
                    _ => {}
                }
            }
        }
    }
    allowed.insert("Tags".to_string());
    decode_allowed.insert("Tags".to_string());
    if rbx_reflection_class_is_a(database, class_name, "TriangleMeshPart") {
        allowed.insert("InitialSize".to_string());
        decode_allowed.insert("InitialSize".to_string());
        renamed.insert("InitialSize".to_string(), "MeshSize".to_string());
    }
    if rbx_reflection_class_is_a(database, class_name, "Model") {
        allowed.insert("WorldPivotData".to_string());
        decode_allowed.insert("WorldPivotData".to_string());
        renamed.insert("WorldPivotData".to_string(), "WorldPivot".to_string());
    }
    let reconstruct_decal_color_map = rbx_reflection_class_is_a(database, class_name, "Decal");
    let reconstruct_weld_enabled = class_name == "WeldConstraint";
    if reconstruct_weld_enabled {
        decode_allowed.insert("State".to_string());
    }
    let output_names = allowed
        .iter()
        .map(|name| renamed.get(name).unwrap_or(name).clone())
        .collect();
    NativePropertyFilter {
        allowed,
        decode_allowed,
        renamed,
        output_names,
        reconstruct_decal_color_map,
        reconstruct_weld_enabled,
    }
}

fn native_overlay_property_is_reconstructed(
    database: &ReflectionDatabase<'_>,
    class_name: &str,
    property_name: &str,
) -> bool {
    if rbx_reflection_class_is_a(database, class_name, "BasePart")
        && matches!(property_name, "Position" | "Orientation" | "Rotation")
    {
        return true;
    }
    if rbx_reflection_class_is_a(database, class_name, "TriangleMeshPart")
        && property_name == "MeshSize"
    {
        return true;
    }
    if rbx_reflection_class_is_a(database, class_name, "Attachment")
        && matches!(
            property_name,
            "Position"
                | "Orientation"
                | "Axis"
                | "SecondaryAxis"
                | "WorldPosition"
                | "WorldOrientation"
                | "WorldAxis"
                | "WorldSecondaryAxis"
                | "WorldCFrame"
        )
    {
        return true;
    }
    if rbx_reflection_class_is_a(database, class_name, "BaseScript") && property_name == "Enabled" {
        return true;
    }
    if class_name == "BodyColors"
        && matches!(
            property_name,
            "HeadColor"
                | "LeftArmColor"
                | "LeftLegColor"
                | "RightArmColor"
                | "RightLegColor"
                | "TorsoColor"
        )
    {
        return true;
    }
    if class_name == "Camera"
        && matches!(property_name, "DiagonalFieldOfView" | "MaxAxisFieldOfView")
    {
        return true;
    }
    if rbx_reflection_class_is_a(database, class_name, "PVInstance") && property_name == "Origin" {
        return true;
    }
    if rbx_reflection_class_is_a(database, class_name, "Decal")
        && property_name == "ColorMapContent"
    {
        return true;
    }
    if class_name == "WeldConstraint" && property_name == "Enabled" {
        return true;
    }
    false
}

fn native_overlay_property_schemas(
    database: &ReflectionDatabase<'_>,
    property_schema_by_class: &PropertySchemaMap,
    native_filters: &HashMap<String, NativePropertyFilter>,
) -> (PropertySchemaMap, PropertySchemaMap, PropertySchemaMap) {
    let combined = property_schema_by_class
        .iter()
        .filter_map(|(class_name, entries)| {
            let native_outputs = native_filters
                .get(class_name)
                .map(|filter| &filter.output_names);
            let overlay = entries
                .iter()
                .filter(|entry| {
                    let Some(descriptor) =
                        rbx_property_descriptor(database, class_name, &entry.name)
                    else {
                        return true;
                    };
                    match &descriptor.kind {
                        RbxPropertyKind::Alias { .. } => false,
                        RbxPropertyKind::Canonical {
                            serialization: RbxPropertySerialization::Migrate(_),
                        } => false,
                        RbxPropertyKind::Canonical {
                            serialization: RbxPropertySerialization::DoesNotSerialize,
                        } => !native_overlay_property_is_reconstructed(
                            database,
                            class_name,
                            &entry.name,
                        ),
                        RbxPropertyKind::Canonical { .. } => {
                            entry.type_id == TYPE_ID_REF
                                || native_outputs
                                    .is_none_or(|outputs| !outputs.contains(&entry.name))
                        }
                        _ => true,
                    }
                })
                .cloned()
                .collect::<Vec<_>>();
            (!overlay.is_empty()).then(|| (class_name.clone(), overlay))
        })
        .collect::<PropertySchemaMap>();
    let mut direct = PropertySchemaMap::new();
    let mut conditional_refs = PropertySchemaMap::new();
    for (class_name, entries) in &combined {
        let native_outputs = native_filters
            .get(class_name)
            .map(|filter| &filter.output_names);
        for entry in entries {
            let target = if entry.type_id == TYPE_ID_REF
                && native_outputs.is_some_and(|outputs| outputs.contains(&entry.name))
            {
                &mut conditional_refs
            } else {
                &mut direct
            };
            target
                .entry(class_name.clone())
                .or_default()
                .push(entry.clone());
        }
    }
    (combined, direct, conditional_refs)
}

fn overlay_property_names_value(
    schema: &PropertySchemaMap,
    native_filters: &HashMap<String, NativePropertyFilter>,
) -> Value {
    Value::Object(
        schema
            .iter()
            .map(|(class_name, entries)| {
                (
                    class_name.clone(),
                    Value::Array(
                        entries
                            .iter()
                            .map(|entry| {
                                if entry.type_id == TYPE_ID_REF
                                    && native_filters.get(class_name).is_some_and(|filter| {
                                        filter.output_names.contains(&entry.name)
                                    })
                                {
                                    Value::Array(vec![
                                        Value::String(entry.name.clone()),
                                        Value::Bool(true),
                                    ])
                                } else {
                                    Value::String(entry.name.clone())
                                }
                            })
                            .collect(),
                    ),
                )
            })
            .collect(),
    )
}

fn conditional_ref_overlay_request(
    instances: &[rbx_binary::FlatInstance],
    schema: &PropertySchemaMap,
) -> (PropertySchemaMap, Value, usize) {
    let mut candidates = HashMap::<(&str, &str), Vec<usize>>::new();
    for (index, instance) in instances.iter().enumerate() {
        let class_name = instance.class.as_str();
        let Some(entries) = schema.get(class_name) else {
            continue;
        };
        for entry in entries {
            let has_native_ref = instance
                .properties
                .iter()
                .find(|(name, _)| name.as_str() == entry.name)
                .map(|(_, value)| value)
                .and_then(rbx_variant_referent)
                .and_then(|referent| referent.as_u128())
                .is_some();
            if !has_native_ref {
                candidates
                    .entry((class_name, entry.name.as_str()))
                    .or_default()
                    .push(index + 1);
            }
        }
    }

    let mut request_schema = PropertySchemaMap::new();
    let mut request_names = Map::new();
    let mut candidate_count = 0;
    for (class_name, entries) in schema {
        let mut class_schema = Vec::new();
        let mut class_names = Vec::new();
        for entry in entries {
            let Some(indices) = candidates.remove(&(class_name.as_str(), entry.name.as_str()))
            else {
                continue;
            };
            candidate_count += indices.len();
            let mut packed = Vec::with_capacity(indices.len() * 3);
            for index in &indices {
                let index = *index as u32;
                packed.push(index as u8);
                packed.push((index >> 8) as u8);
                packed.push((index >> 16) as u8);
            }
            class_schema.push(entry.clone());
            class_names.push(Value::Array(vec![
                Value::String(entry.name.clone()),
                json!({
                    "packed": base64::encode(packed),
                    "count": indices.len(),
                }),
            ]));
        }
        if !class_schema.is_empty() {
            request_schema.insert(class_name.clone(), class_schema);
            request_names.insert(class_name.clone(), Value::Array(class_names));
        }
    }
    (
        request_schema,
        Value::Object(request_names),
        candidate_count,
    )
}

#[expect(
    clippy::too_many_arguments,
    reason = "native overlay decoding keeps its transport schema explicit"
)]
fn fetch_native_overlay_batch_once(
    bridge: &BridgeServer,
    service: &str,
    start_index: usize,
    take_count: usize,
    instance_count: usize,
    overlay_id: &str,
    overlay_variant: &str,
    overlay_names: &Value,
    overlay_schema: &PropertySchemaMap,
    enum_value_names_by_type: &EnumValueNameMap,
    class_names: &[String],
) -> Result<NativeOverlayFetch> {
    let started = Instant::now();
    let (batch, metrics) = fetch_typed_payload_with_size::<CompactBatchPayload, _>(
        DEFAULT_EXPORT_CHUNK_SIZE,
        |chunk_start, max_len| {
            bridge.call_chunk(
                "getEditorBinaryOverlayChunk",
                json!({
                    "service": service,
                    "startIndex": start_index,
                    "maxCount": take_count,
                    "chunkStart": chunk_start,
                    "maxLen": max_len,
                    "overlayId": overlay_id,
                    "overlayVariant": overlay_variant,
                    "overlayPropertiesByClass": overlay_names,
                    "supportsStableInstanceIds": false,
                }),
            )
        },
    )?;
    if batch.format != NATIVE_OVERLAY_PROTOCOL_VERSION
        || !is_supported_bridge_codec(&batch.codec_version)
    {
        bail!(
            "Invalid native overlay format {} with codec {} for {}",
            batch.format,
            batch.codec_version,
            service
        );
    }
    if !batch.debug_ids.is_empty() {
        bail!("Native overlay for {service} used the legacy debug id array");
    }
    if !batch.debug_id_buffer.is_null() || !batch.debug_id_fallbacks.is_empty() {
        bail!("Native overlay for {service} returned unexpected debug id data");
    }
    let compact_expand_started = Instant::now();
    let numeric_enum_values = compact_v5_codec_uses_numeric_enum_values(&batch.codec_version);
    let flat_fixed_values = batch.codec_version == BRIDGE_CODEC_VERSION_SCHEMA5;
    let items = parse_native_overlay_items(
        Value::Array(batch.items),
        batch.strings,
        start_index,
        take_count,
        overlay_schema,
        enum_value_names_by_type,
        numeric_enum_values,
        flat_fixed_values,
        class_names,
    )
    .with_context(|| format!("Invalid native overlay items for {service}"))?;
    if batch.total != instance_count {
        bail!(
            "Native overlay range for {service} returned total={}; expected total={} at start={start_index}",
            batch.total,
            instance_count,
        );
    }
    Ok(NativeOverlayFetch {
        metrics,
        compact_expand_ms: elapsed_ms(compact_expand_started),
        request_ms: elapsed_ms(started),
        items,
    })
}

fn merge_native_overlay_items(
    target: &mut [SnapshotInstance],
    additional: Vec<NativeOverlayItem>,
) -> Result<()> {
    for additional in additional {
        let target_instance = additional
            .instance_index
            .checked_sub(1)
            .and_then(|index| target.get_mut(index))
            .context("Native overlay instance index is out of range")?;
        if target_instance.instance_index != Some(additional.instance_index)
            || (!additional.class_name.is_empty()
                && additional.class_name != target_instance.class_name)
        {
            bail!(
                "Native overlay passes disagree at instance {}",
                additional.instance_index
            );
        }
        target_instance.properties.extend(additional.properties);
        target_instance.attributes.extend(additional.attributes);
    }
    Ok(())
}

fn rbx_instance_to_settings_records(
    instance: &rbx_dom_weak::Instance,
    database: &ReflectionDatabase<'_>,
    refs: &BytecodeModelImportRefs,
    elide_defaults: bool,
    native_filter: Option<&NativePropertyFilter>,
) -> (Map<String, Value>, Map<String, Value>, Option<String>) {
    rbx_properties_to_settings_records(
        instance.class.as_str(),
        instance.properties.iter(),
        database,
        refs,
        elide_defaults,
        false,
        false,
        native_filter,
    )
}

fn rbx_properties_to_settings_records<'a>(
    class_name: &str,
    property_entries: impl IntoIterator<Item = (&'a rbx_dom_weak::Ustr, &'a RbxVariant)>,
    database: &ReflectionDatabase<'_>,
    refs: &BytecodeModelImportRefs,
    elide_defaults: bool,
    defaults_already_elided: bool,
    native_properties_pre_filtered: bool,
    native_filter: Option<&NativePropertyFilter>,
) -> (Map<String, Value>, Map<String, Value>, Option<String>) {
    let mut properties = Map::new();
    let mut attributes = Map::new();
    let mut source = None;

    for (property_name, variant) in property_entries {
        let property_name = property_name.as_str();
        if let RbxVariant::Attributes(rbx_attributes) = variant {
            attributes.extend(rbx_attributes_to_settings_map(
                rbx_attributes,
                database,
                refs,
            ));
            continue;
        }
        if model_property_name_is_skipped(property_name) {
            continue;
        }
        if property_name.eq_ignore_ascii_case("Source") && is_lua_source_class(class_name) {
            source = rbx_variant_to_source_string(variant);
            continue;
        }
        if !native_properties_pre_filtered
            && native_filter.is_some_and(|filter| !filter.allowed.contains(property_name))
        {
            continue;
        }
        if elide_defaults
            && rbx_variant_referent(variant).is_some_and(|referent| {
                imported_instance_index(refs, referent).is_none()
                    && !refs.path_segments_by_ref.contains_key(&referent)
            })
        {
            continue;
        }
        if elide_defaults
            && !defaults_already_elided
            && database
                .classes
                .get(class_name)
                .and_then(|class| database.find_default_property(class, property_name))
                == Some(variant)
        {
            continue;
        }
        let descriptor = rbx_model_property_descriptor(database, class_name, property_name);
        if let Some(value) = rbx_variant_to_settings_json(variant, descriptor, database, refs) {
            let output_name = native_filter
                .and_then(|filter| filter.renamed.get(property_name))
                .map(String::as_str)
                .unwrap_or(property_name);
            properties.insert(output_name.to_string(), value);
        }
    }

    if is_lua_source_class(class_name) {
        properties.insert(
            "Source".to_string(),
            Value::String("__SOURCE_EXTERNAL__".to_string()),
        );
        source = Some(source.unwrap_or_default());
    }

    (properties, attributes, source)
}

fn rbx_variant_to_source_string(value: &RbxVariant) -> Option<String> {
    match value {
        RbxVariant::String(value) => Some(value.clone()),
        RbxVariant::BinaryString(value) => {
            Some(String::from_utf8_lossy(value.as_ref()).to_string())
        }
        _ => None,
    }
}

fn rbx_attributes_to_settings_map(
    attributes: &RbxAttributes,
    database: &ReflectionDatabase<'_>,
    refs: &BytecodeModelImportRefs,
) -> Map<String, Value> {
    let mut out = Map::new();
    for (name, value) in attributes.iter() {
        let value = match value {
            RbxVariant::BinaryString(value) => Some(Value::String(
                String::from_utf8_lossy(value.as_ref()).into_owned(),
            )),
            RbxVariant::EnumItem(value) => {
                let mut encoded = rbx_enum_to_settings_json(Some(&value.ty), value.value, database);
                if let Some(enum_type) = encoded
                    .as_object_mut()
                    .and_then(|object| object.get_mut("enumType"))
                    .and_then(|value| value.as_str())
                    .map(strip_enum_prefix)
                    .map(ToString::to_string)
                {
                    encoded["enumType"] = Value::String(enum_type);
                }
                Some(encoded)
            }
            _ => rbx_variant_to_settings_json(value, None, database, refs),
        };
        if let Some(value) = value {
            out.insert(name.clone(), value);
        }
    }
    out
}

fn rbx_variant_to_settings_json(
    value: &RbxVariant,
    descriptor: Option<&RbxPropertyDescriptor<'_>>,
    database: &ReflectionDatabase<'_>,
    refs: &BytecodeModelImportRefs,
) -> Option<Value> {
    match value {
        RbxVariant::Bool(value) => Some(Value::Bool(*value)),
        RbxVariant::Int32(value) => Some(Value::Number(Number::from(*value))),
        RbxVariant::Int64(value) => Some(Value::Number(Number::from(*value))),
        RbxVariant::Float32(value) => json_number_f64(*value as f64),
        RbxVariant::Float64(value) => json_number_f64(*value),
        RbxVariant::String(value) => Some(Value::String(value.clone())),
        RbxVariant::BinaryString(value) => {
            Some(binary_payload_json("BinaryString", value.as_ref()))
        }
        RbxVariant::ContentId(value) => Some(Value::String(value.as_str().to_string())),
        RbxVariant::Content(value) => rbx_content_to_settings_json(value, refs),
        RbxVariant::Tags(value) => Some(Value::Array(
            value.iter().map(|tag| Value::String(tag.to_string())).collect(),
        )),
        RbxVariant::Ref(value) => Some(rbx_ref_to_settings_json(*value, refs)),
        RbxVariant::Vector2(value) => Some(json!({"_type":"Vector2","x":value.x,"y":value.y})),
        RbxVariant::Vector3(value) => Some(json!({"_type":"Vector3","x":value.x,"y":value.y,"z":value.z})),
        RbxVariant::Vector2int16(value) => Some(json!({"_type":"Vector2int16","x":value.x,"y":value.y})),
        RbxVariant::Vector3int16(value) => Some(json!({"_type":"Vector3int16","x":value.x,"y":value.y,"z":value.z})),
        RbxVariant::UDim(value) => Some(json!({"_type":"UDim","scale":value.scale,"offset":value.offset})),
        RbxVariant::UDim2(value) => Some(json!({
            "_type":"UDim2",
            "xScale": value.x.scale,
            "xOffset": value.x.offset,
            "yScale": value.y.scale,
            "yOffset": value.y.offset,
        })),
        RbxVariant::Color3(value) => Some(json!({"_type":"Color3","r":value.r,"g":value.g,"b":value.b})),
        RbxVariant::Color3uint8(value) => {
            let color = RbxColor3::from(*value);
            Some(json!({"_type":"Color3","r":color.r,"g":color.g,"b":color.b}))
        }
        RbxVariant::BrickColor(value) => Some(json!({"_type":"BrickColor","number": *value as u16})),
        RbxVariant::CFrame(value) => Some(rbx_cframe_to_settings_json(*value)),
        RbxVariant::OptionalCFrame(value) => value.map(rbx_cframe_to_settings_json).or(Some(Value::Null)),
        RbxVariant::Rect(value) => Some(json!({
            "_type":"Rect",
            "minX": value.min.x,
            "minY": value.min.y,
            "maxX": value.max.x,
            "maxY": value.max.y,
        })),
        RbxVariant::NumberRange(value) => Some(json!({"_type":"NumberRange","min":value.min,"max":value.max})),
        RbxVariant::NumberSequence(value) => Some(Value::Object(Map::from_iter([
            ("_type".to_string(), Value::String("NumberSequence".to_string())),
            ("keypoints".to_string(), Value::Array(value.keypoints.iter().map(|keypoint| json!({
                "time": keypoint.time,
                "value": keypoint.value,
                "envelope": keypoint.envelope,
            })).collect())),
        ]))),
        RbxVariant::ColorSequence(value) => Some(Value::Object(Map::from_iter([
            ("_type".to_string(), Value::String("ColorSequence".to_string())),
            ("keypoints".to_string(), Value::Array(value.keypoints.iter().map(|keypoint| json!({
                "time": keypoint.time,
                "value": {"r": keypoint.color.r, "g": keypoint.color.g, "b": keypoint.color.b},
            })).collect())),
        ]))),
        RbxVariant::PhysicalProperties(value) => Some(rbx_physical_properties_to_settings_json(*value)),
        RbxVariant::Font(value) => Some(rbx_font_to_settings_json(value)),
        RbxVariant::Enum(value) => {
            let enum_name = descriptor.and_then(|descriptor| match &descriptor.data_type {
                RbxDataType::Enum(enum_name) => Some(*enum_name),
                _ => None,
            });
            Some(rbx_enum_to_settings_json(enum_name, value.to_u32(), database))
        }
        RbxVariant::EnumItem(value) => Some(rbx_enum_to_settings_json(Some(&value.ty), value.value, database)),
        RbxVariant::Attributes(attributes) => Some(Value::Object(rbx_attributes_to_settings_map(attributes, database, refs))),
        RbxVariant::Axes(value) => Some(json!({
            "_type": "Axes",
            "axes": Value::Array(bitmask_names(value.bits(), &AXIS_NAMES)),
        })),
        RbxVariant::Faces(value) => Some(json!({
            "_type": "Faces",
            "faces": Value::Array(bitmask_names(value.bits(), &FACE_NAMES)),
        })),
        RbxVariant::Ray(value) => Some(json!({
            "_type": "Ray",
            "origin": {"x": value.origin.x, "y": value.origin.y, "z": value.origin.z},
            "direction": {"x": value.direction.x, "y": value.direction.y, "z": value.direction.z},
        })),
        RbxVariant::MaterialColors(value) => {
            Some(binary_payload_json("MaterialColors", &value.encode()))
        }
        RbxVariant::SharedString(value) => {
            Some(binary_payload_json("SharedString", value.as_ref()))
        }
        RbxVariant::NetAssetRef(value) => {
            Some(binary_payload_json("NetAssetRef", value.data()))
        }
        RbxVariant::Region3(value) => Some(json!({
            "_type": "Region3",
            "min": {"x": value.min.x, "y": value.min.y, "z": value.min.z},
            "max": {"x": value.max.x, "y": value.max.y, "z": value.max.z},
        })),
        RbxVariant::Region3int16(value) => Some(json!({
            "_type": "Region3int16",
            "min": {"x": value.min.x, "y": value.min.y, "z": value.min.z},
            "max": {"x": value.max.x, "y": value.max.y, "z": value.max.z},
        })),
        RbxVariant::UniqueId(_)
        | RbxVariant::SecurityCapabilities(_)
        => None,
        _ => None,
    }
}

fn json_number_f64(value: f64) -> Option<Value> {
    if let Some(number) = Number::from_f64(value) {
        return Some(Value::Number(number));
    }
    Some(nonfinite_float_json(value))
}

fn nonfinite_float_json(value: f64) -> Value {
    let text = if value.is_nan() {
        "nan"
    } else if value > 0.0 {
        "inf"
    } else {
        "-inf"
    };
    json!({ "_type": "Float", "value": text })
}

fn nonfinite_float_from_json(value: &Value) -> Option<f64> {
    let object = value.as_object()?;
    let encoded = if object.get("_type").and_then(Value::as_str) == Some("Float") {
        object.get("value").and_then(Value::as_str)
    } else if object.get("t").and_then(Value::as_str) == Some("numeric") {
        object.get("v").and_then(Value::as_str)
    } else {
        None
    }?;
    match encoded {
        "nan" => Some(f64::NAN),
        "inf" => Some(f64::INFINITY),
        "-inf" => Some(f64::NEG_INFINITY),
        _ => None,
    }
}

fn canonicalize_nonfinite_float_json(value: Value) -> Value {
    nonfinite_float_from_json(&value)
        .map(nonfinite_float_json)
        .unwrap_or(value)
}

fn rbx_cframe_to_settings_json(value: RbxCFrame) -> Value {
    json!({
        "_type": "CFrame",
        "components": [
            value.position.x,
            value.position.y,
            value.position.z,
            value.orientation.x.x,
            value.orientation.x.y,
            value.orientation.x.z,
            value.orientation.y.x,
            value.orientation.y.y,
            value.orientation.y.z,
            value.orientation.z.x,
            value.orientation.z.y,
            value.orientation.z.z,
        ]
    })
}

fn rbx_content_to_settings_json(
    value: &RbxContent,
    refs: &BytecodeModelImportRefs,
) -> Option<Value> {
    match value.value() {
        RbxContentType::None => Some(Value::String(String::new())),
        RbxContentType::Uri(uri) => Some(Value::String(uri.clone())),
        RbxContentType::Object(referent) => Some(rbx_ref_to_settings_json(*referent, refs)),
        _ => None,
    }
}

fn rbx_ref_to_settings_json(referent: RbxRef, refs: &BytecodeModelImportRefs) -> Value {
    let mut out = Map::new();
    out.insert("_type".to_string(), Value::String("Ref".to_string()));
    if let Some(new_index) = imported_instance_index(refs, referent) {
        out.insert(
            "instanceIndex".to_string(),
            Value::Number(Number::from((new_index + 1) as u64)),
        );
        if let Some(settings_id) = refs.settings_id_by_ref.get(&referent) {
            out.insert("settingsId".to_string(), Value::String(settings_id.clone()));
        }
    }
    let path_segments = refs.path_segments_by_ref.get(&referent).or_else(|| {
        imported_instance_index(refs, referent)
            .and_then(|index| refs.path_segments_by_index.get(index))
            .and_then(Option::as_ref)
    });
    if let Some(path_segments) = path_segments {
        out.insert(
            "pathSegments".to_string(),
            Value::Array(path_segments.iter().cloned().map(Value::String).collect()),
        );
    }
    Value::Object(out)
}

fn rbx_enum_to_settings_json(
    enum_name: Option<&str>,
    enum_value: u32,
    database: &ReflectionDatabase<'_>,
) -> Value {
    let mut out = Map::new();
    out.insert("_type".to_string(), Value::String("EnumItem".to_string()));
    if let Some(enum_name) = enum_name.map(strip_enum_prefix) {
        out.insert(
            "enumType".to_string(),
            Value::String(format!("Enum.{enum_name}")),
        );
        if let Some(name) = enum_item_name_by_value(database, enum_name, enum_value) {
            out.insert("name".to_string(), Value::String(name));
        }
    }
    out.entry("name".to_string())
        .or_insert_with(|| Value::String(enum_value.to_string()));
    out.insert("value".to_string(), Value::Number(Number::from(enum_value)));
    Value::Object(out)
}

fn rbx_font_to_settings_json(value: &RbxFont) -> Value {
    let mut out = Map::new();
    out.insert("_type".to_string(), Value::String("Font".to_string()));
    out.insert("family".to_string(), Value::String(value.family.clone()));
    out.insert(
        "weight".to_string(),
        Value::String(rbx_font_weight_name(value.weight).to_string()),
    );
    out.insert(
        "style".to_string(),
        Value::String(rbx_font_style_name(value.style).to_string()),
    );
    if let Some(cached_face_id) = value.cached_face_id.as_ref()
        && !cached_face_id.is_empty()
    {
        out.insert(
            "cachedFaceId".to_string(),
            Value::String(cached_face_id.clone()),
        );
    }
    Value::Object(out)
}

fn rbx_physical_properties_to_settings_json(value: RbxPhysicalProperties) -> Value {
    match value {
        RbxPhysicalProperties::Default => json!({
            "_type": "PhysicalProperties",
            "customPhysics": false,
        }),
        RbxPhysicalProperties::Custom(value) => json!({
            "_type": "PhysicalProperties",
            "density": value.density(),
            "friction": value.friction(),
            "elasticity": value.elasticity(),
            "frictionWeight": value.friction_weight(),
            "elasticityWeight": value.elasticity_weight(),
            "acousticAbsorption": value.acoustic_absorption(),
        }),
    }
}

fn rbx_font_weight_name(value: RbxFontWeight) -> &'static str {
    match value {
        RbxFontWeight::Thin => "Thin",
        RbxFontWeight::ExtraLight => "ExtraLight",
        RbxFontWeight::Light => "Light",
        RbxFontWeight::Regular => "Regular",
        RbxFontWeight::Medium => "Medium",
        RbxFontWeight::SemiBold => "SemiBold",
        RbxFontWeight::Bold => "Bold",
        RbxFontWeight::ExtraBold => "ExtraBold",
        RbxFontWeight::Heavy => "Heavy",
        _ => "Regular",
    }
}

fn rbx_font_style_name(value: RbxFontStyle) -> &'static str {
    match value {
        RbxFontStyle::Normal => "Normal",
        RbxFontStyle::Italic => "Italic",
        _ => "Normal",
    }
}

fn bytecode_selector<'a>(
    index: Option<usize>,
    settings_id: Option<&'a str>,
    name: Option<&'a str>,
    class_name: Option<&'a str>,
) -> Result<InstanceSelector<'a>> {
    let mut selector = None;
    let mut count = 0;
    if let Some(index) = index {
        selector = Some(InstanceSelector::Index(index));
        count += 1;
    }
    if let Some(settings_id) = settings_id.filter(|value| !value.is_empty()) {
        selector = Some(InstanceSelector::SettingsId(settings_id));
        count += 1;
    }
    if let Some(name) = name.filter(|value| !value.is_empty()) {
        selector = Some(InstanceSelector::Name(name));
        count += 1;
    }
    if let Some(class_name) = class_name.filter(|value| !value.is_empty()) {
        selector = Some(InstanceSelector::ClassName(class_name));
        count += 1;
    }
    match (count, selector) {
        (1, Some(selector)) => Ok(selector),
        (0, _) => bail!("Provide one selector: --index, --settings-id, --name, or --class-name"),
        _ => bail!("Provide only one selector"),
    }
}

fn bytecode_parent_index(
    document: &SettingsBytecode,
    no_parent: bool,
    index: Option<usize>,
    settings_id: Option<&str>,
    name: Option<&str>,
    class_name: Option<&str>,
) -> Result<Option<usize>> {
    if no_parent {
        let specified = index.is_some()
            || settings_id.is_some_and(|value| !value.is_empty())
            || name.is_some_and(|value| !value.is_empty())
            || class_name.is_some_and(|value| !value.is_empty());
        if specified {
            bail!("--no-parent cannot be combined with a parent selector");
        }
        return Ok(None);
    }

    let specified = index.is_some()
        || settings_id.is_some_and(|value| !value.is_empty())
        || name.is_some_and(|value| !value.is_empty())
        || class_name.is_some_and(|value| !value.is_empty());
    if specified {
        let selector = bytecode_selector(index, settings_id, name, class_name)?;
        return instance_api::find_unique_instance_index(document, selector)?
            .map(Some)
            .ok_or_else(|| anyhow::anyhow!("Parent instance was not found"));
    }

    document
        .instances
        .iter()
        .position(|instance| instance.parent_index.is_none())
        .or_else(|| (!document.instances.is_empty()).then_some(0))
        .map(Some)
        .ok_or_else(|| anyhow::anyhow!("Cannot infer parent for empty settings bytecode"))
}

fn parse_property_scope(raw: &str) -> Result<PropertyScope> {
    match raw.to_ascii_lowercase().as_str() {
        "auto" => Ok(PropertyScope::Auto),
        "metadata" | "meta" => Ok(PropertyScope::Metadata),
        "property" | "prop" => Ok(PropertyScope::Property),
        "attribute" | "attr" => Ok(PropertyScope::Attribute),
        other => bail!("Invalid property scope: {other}"),
    }
}

fn parse_property_predicates(raw: &[String]) -> Result<Vec<PropertyPredicate>> {
    raw.iter()
        .map(|item| {
            if let Some((name, value)) = item.split_once('=') {
                let value: Value = serde_json::from_str(value)
                    .with_context(|| format!("Invalid predicate JSON value in {item}"))?;
                Ok(PropertyPredicate::equals(name.trim(), value))
            } else {
                Ok(PropertyPredicate::exists(item.trim()))
            }
        })
        .collect()
}

fn parse_property_assignments(raw: &[String]) -> Result<Map<String, Value>> {
    let mut out = Map::new();
    for item in raw {
        let Some((name, value)) = item.split_once('=') else {
            bail!("Expected NAME=JSON assignment: {item}");
        };
        let name = name.trim();
        if name.is_empty() {
            bail!("Property assignment name cannot be empty: {item}");
        }
        let value: Value = serde_json::from_str(value)
            .with_context(|| format!("Invalid assignment JSON value in {item}"))?;
        out.insert(name.to_string(), value);
    }
    Ok(out)
}

fn generate_sourcemap_command(args: GenerateSourcemapArgs) -> Result<()> {
    let project_root = canonical_path(&args.project_root).with_context(|| {
        format!(
            "Failed to resolve project root: {}",
            args.project_root.display()
        )
    })?;
    generate_project_sourcemap(&project_root)
}

fn adaptive_tune_cache_path(project_root: &Path) -> PathBuf {
    project_root.join(".renium-adaptive.json")
}

fn adaptive_tune_cache_key(
    bridge_info: &BridgeInfoPayload,
    chunk_size: usize,
    performance_mode: PerformanceMode,
    modified_default_bypass: bool,
) -> String {
    format!(
        "bridge={}:{};protocol={};codec={};chunk_frame={};compact_value={};chunk_size={};performance={};modified_default_bypass={}",
        bridge_info.bridge_version,
        bridge_info.bridge_build_unix,
        bridge_info.protocol_version,
        bridge_info.codec_version,
        bridge_info.chunk_frame_protocol_version,
        bridge_info.compact_value_protocol_version,
        chunk_size,
        performance_mode.as_str(),
        modified_default_bypass
    )
}

fn empty_adaptive_tune_cache(cache_key: &str) -> AdaptiveTuneCache {
    AdaptiveTuneCache {
        version: ADAPTIVE_TUNE_CACHE_VERSION,
        cache_key: cache_key.to_string(),
        ..AdaptiveTuneCache::default()
    }
}

fn load_adaptive_tune_cache(project_root: &Path, expected_cache_key: &str) -> AdaptiveTuneCache {
    let path = adaptive_tune_cache_path(project_root);
    let Ok(cache) = read_json_file::<AdaptiveTuneCache>(&path) else {
        return empty_adaptive_tune_cache(expected_cache_key);
    };
    if cache.version != ADAPTIVE_TUNE_CACHE_VERSION {
        println!(
            "[renium] adaptive tune cache version mismatch at {} (found {}, expected {}); ignoring cached tunes",
            path.display(),
            cache.version,
            ADAPTIVE_TUNE_CACHE_VERSION
        );
        let _ = fs::remove_file(&path);
        return empty_adaptive_tune_cache(expected_cache_key);
    }
    if cache.cache_key != expected_cache_key {
        println!(
            "[renium] adaptive tune cache key mismatch at {}; ignoring cached tunes",
            path.display()
        );
        let _ = fs::remove_file(&path);
        return empty_adaptive_tune_cache(expected_cache_key);
    }
    cache
}

fn write_adaptive_tune_cache(project_root: &Path, cache: &AdaptiveTuneCache) {
    let path = adaptive_tune_cache_path(project_root);
    let cache_to_write = AdaptiveTuneCache {
        version: ADAPTIVE_TUNE_CACHE_VERSION,
        cache_key: cache.cache_key.clone(),
        services: cache.services.clone(),
    };
    if let Err(err) = write_json_file(&path, &cache_to_write, true) {
        println!(
            "[renium] warning: failed to write adaptive tuning cache {}: {err:#}",
            path.display()
        );
    }
}

#[expect(
    clippy::large_enum_variant,
    reason = "service payloads stay inline to avoid an extra heap allocation on every import task"
)]
enum DirectImportTask {
    Service {
        service: String,
        parts: ExportedSnapshotParts,
    },
    Subtree(DirectImportSubtreeTask),
}

struct DirectImportTaskQueueState {
    services: VecDeque<DirectImportTask>,
    subtrees: VecDeque<DirectImportTask>,
    prefer_subtree: bool,
    active_workers: usize,
    closed: bool,
}

struct DirectImportTaskQueue {
    state: Mutex<DirectImportTaskQueueState>,
    ready: Condvar,
    worker_gate: Condvar,
}

impl DirectImportTaskQueue {
    fn new(active_workers: usize) -> Self {
        Self {
            state: Mutex::new(DirectImportTaskQueueState {
                services: VecDeque::new(),
                subtrees: VecDeque::new(),
                prefer_subtree: false,
                active_workers: active_workers.max(1),
                closed: false,
            }),
            ready: Condvar::new(),
            worker_gate: Condvar::new(),
        }
    }

    fn enqueue_service(&self, task: DirectImportTask) -> bool {
        let mut state = match self.state.lock() {
            Ok(lock) => lock,
            Err(poisoned) => poisoned.into_inner(),
        };
        if state.closed {
            return false;
        }
        state.services.push_back(task);
        self.ready.notify_one();
        true
    }

    fn enqueue_subtree(&self, task: DirectImportTask) -> bool {
        let mut state = match self.state.lock() {
            Ok(lock) => lock,
            Err(poisoned) => poisoned.into_inner(),
        };
        if state.closed {
            return false;
        }
        state.subtrees.push_back(task);
        self.ready.notify_one();
        true
    }

    fn receive(&self, worker_index: usize) -> Option<DirectImportTask> {
        let mut state = match self.state.lock() {
            Ok(lock) => lock,
            Err(poisoned) => poisoned.into_inner(),
        };
        loop {
            if worker_index >= state.active_workers && !state.closed {
                state = match self.worker_gate.wait(state) {
                    Ok(lock) => lock,
                    Err(poisoned) => poisoned.into_inner(),
                };
                continue;
            }
            if !state.services.is_empty() && !state.subtrees.is_empty() {
                state.prefer_subtree = !state.prefer_subtree;
                return if state.prefer_subtree {
                    state.subtrees.pop_front()
                } else {
                    state.services.pop_front()
                };
            }
            if let Some(task) = state.services.pop_front() {
                return Some(task);
            }
            if let Some(task) = state.subtrees.pop_front() {
                return Some(task);
            }
            if state.closed {
                return None;
            }
            state = match self.ready.wait(state) {
                Ok(lock) => lock,
                Err(poisoned) => poisoned.into_inner(),
            };
        }
    }

    fn activate_workers(&self, active_workers: usize) {
        let mut state = match self.state.lock() {
            Ok(lock) => lock,
            Err(poisoned) => poisoned.into_inner(),
        };
        state.active_workers = state.active_workers.max(active_workers);
        self.worker_gate.notify_all();
        self.ready.notify_all();
    }

    fn close(&self) {
        let mut state = match self.state.lock() {
            Ok(lock) => lock,
            Err(poisoned) => poisoned.into_inner(),
        };
        state.closed = true;
        self.worker_gate.notify_all();
        self.ready.notify_all();
    }
}

