    #[test]
    fn get_property_source_falls_back_to_externalized_mirror() {
        let dir = link_test_dir("get-source-mirror");
        let service_dir = dir.join("src").join("ReplicatedStorage");
        fs::create_dir_all(&service_dir).unwrap();
        let settings_file = service_settings_path(&service_dir);
        SettingsBytecode {
            version: SETTINGS_BINARY_VERSION,
            instances: vec![
                SettingsBytecodeInstance {
                    settings_id: "root".into(),
                    name: "ReplicatedStorage".into(),
                    class_name: "ReplicatedStorage".into(),
                    parent_index: None,
                    properties: Map::new(),
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "editor:1".into(),
                    name: "Mod".into(),
                    class_name: "ModuleScript".into(),
                    parent_index: Some(0),
                    properties: Map::new(),
                    attributes: Map::new(),
                },
            ],
        }
        .write_file(&settings_file)
        .unwrap();
        fs::write(service_dir.join("Mod.luau"), "return 123\n").unwrap();
        let settings_arg = settings_file.to_string_lossy().to_string();

        let args = BytecodeGetPropertyArgs::try_parse_from([
            "bytecode-get-property",
            "-f",
            &settings_arg,
            "-n",
            "Mod",
            "-p",
            "Source",
        ])
        .unwrap();
        assert!(bytecode_get_property(args).is_ok());

        fs::remove_file(service_dir.join("Mod.luau")).unwrap();
        let args = BytecodeGetPropertyArgs::try_parse_from([
            "bytecode-get-property",
            "-f",
            &settings_arg,
            "-n",
            "Mod",
            "-p",
            "Source",
        ])
        .unwrap();
        let err = bytecode_get_property(args).unwrap_err();
        assert!(err.to_string().contains("Property not found"), "{err}");
        fs::remove_dir_all(dir).unwrap();
    }

