    #[test]
    fn clone_instance_rebinds_internal_ref_properties() {
        let unique = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let project_root = std::env::temp_dir().join(format!("renium-clone-ref-{unique}"));
        let service_dir = project_root.join("src").join("Workspace");
        fs::create_dir_all(&service_dir).unwrap();
        let settings_path = service_settings_path(&service_dir);

        let mut model_properties = Map::new();
        model_properties.insert(
            "PrimaryPart".to_string(),
            json!({ "_type": "Ref", "instanceIndex": 3 }),
        );
        model_properties.insert(
            "ExternalRef".to_string(),
            json!({ "_type": "Ref", "instanceIndex": 6 }),
        );
        let mut weld_properties = Map::new();
        weld_properties.insert(
            "Part0".to_string(),
            json!({ "_type": "Ref", "instanceIndex": 3 }),
        );
        weld_properties.insert(
            "Part1".to_string(),
            json!({ "_type": "Ref", "instanceIndex": 4 }),
        );

        let document = SettingsBytecode {
            version: SETTINGS_BINARY_VERSION,
            instances: vec![
                SettingsBytecodeInstance {
                    settings_id: "root".to_string(),
                    name: "Workspace".to_string(),
                    class_name: "Workspace".to_string(),
                    parent_index: None,
                    properties: Map::new(),
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "model".to_string(),
                    name: "Model".to_string(),
                    class_name: "Model".to_string(),
                    parent_index: Some(0),
                    properties: model_properties,
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "part-a".to_string(),
                    name: "PartA".to_string(),
                    class_name: "Part".to_string(),
                    parent_index: Some(1),
                    properties: Map::new(),
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "part-b".to_string(),
                    name: "PartB".to_string(),
                    class_name: "Part".to_string(),
                    parent_index: Some(1),
                    properties: Map::new(),
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "weld".to_string(),
                    name: "Weld".to_string(),
                    class_name: "WeldConstraint".to_string(),
                    parent_index: Some(1),
                    properties: weld_properties,
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "outside".to_string(),
                    name: "Outside".to_string(),
                    class_name: "Part".to_string(),
                    parent_index: Some(0),
                    properties: Map::new(),
                    attributes: Map::new(),
                },
            ],
        };
        document.write_file(&settings_path).unwrap();

        bytecode_clone_instance(BytecodeCloneInstanceArgs {
            service_or_file: None,
            settings_file: Some(settings_path.clone()),
            service: "Workspace".to_string(),
            settings_id: Some("model".to_string()),
            index: None,
            name: None,
            class_name: None,
            parent_index: Some(0),
            parent_settings_id: None,
            parent_name: None,
            parent_class_name: None,
            pretty: false,
        })
        .unwrap();

        let cloned = SettingsBytecode::read_file(&settings_path).unwrap();
        let cloned_model_index = cloned
            .instances
            .iter()
            .position(|instance| instance.name == "Model Copy")
            .unwrap();
        let cloned_part_a_index = cloned
            .instances
            .iter()
            .position(|instance| {
                instance.parent_index == Some(cloned_model_index) && instance.name == "PartA"
            })
            .unwrap();
        let cloned_part_b_index = cloned
            .instances
            .iter()
            .position(|instance| {
                instance.parent_index == Some(cloned_model_index) && instance.name == "PartB"
            })
            .unwrap();
        let cloned_weld_index = cloned
            .instances
            .iter()
            .position(|instance| {
                instance.parent_index == Some(cloned_model_index) && instance.name == "Weld"
            })
            .unwrap();

        assert_ref_index(
            cloned.instances[cloned_model_index]
                .properties
                .get("PrimaryPart"),
            cloned_part_a_index + 1,
        );
        assert_ref_index(
            cloned.instances[cloned_model_index]
                .properties
                .get("ExternalRef"),
            6,
        );
        assert_ref_index(
            cloned.instances[cloned_weld_index].properties.get("Part0"),
            cloned_part_a_index + 1,
        );
        assert_ref_index(
            cloned.instances[cloned_weld_index].properties.get("Part1"),
            cloned_part_b_index + 1,
        );

        let _ = fs::remove_dir_all(project_root);
    }

    #[test]
    fn bytecode_move_instance_cross_service_preserves_inline_source() {
        let project_root = link_test_dir("move-cross-service");
        let src_root = project_root.join("src");
        let source_dir = src_root.join("ServerStorage");
        let target_dir = src_root.join("ReplicatedStorage");
        fs::create_dir_all(&source_dir).unwrap();
        fs::create_dir_all(&target_dir).unwrap();
        let source_settings = service_settings_path(&source_dir);
        let target_settings = service_settings_path(&target_dir);
        let mut source_properties = Map::new();
        source_properties.insert("Source".to_string(), json!("return 42"));
        SettingsBytecode {
            version: SETTINGS_BINARY_VERSION,
            instances: vec![
                SettingsBytecodeInstance {
                    settings_id: "source-root".into(),
                    name: "ServerStorage".into(),
                    class_name: "ServerStorage".into(),
                    parent_index: None,
                    properties: Map::new(),
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "script".into(),
                    name: "LinkedScript".into(),
                    class_name: "ModuleScript".into(),
                    parent_index: Some(0),
                    properties: source_properties,
                    attributes: Map::new(),
                },
            ],
        }
        .write_file(&source_settings)
        .unwrap();
        SettingsBytecode {
            version: SETTINGS_BINARY_VERSION,
            instances: vec![SettingsBytecodeInstance {
                settings_id: "target-root".into(),
                name: "ReplicatedStorage".into(),
                class_name: "ReplicatedStorage".into(),
                parent_index: None,
                properties: Map::new(),
                attributes: Map::new(),
            }],
        }
        .write_file(&target_settings)
        .unwrap();

        bytecode_move_instance(BytecodeMoveInstanceArgs {
            service_or_file: None,
            settings_file: Some(source_settings.clone()),
            service: "ServerStorage".into(),
            settings_id: Some("script".into()),
            index: None,
            name: None,
            class_name: None,
            target_settings_file: target_settings.clone(),
            target_service: "ReplicatedStorage".into(),
            parent_index: None,
            parent_settings_id: Some("target-root".into()),
            parent_name: None,
            parent_class_name: None,
            pretty: false,
        })
        .unwrap();

        let source_after = SettingsBytecode::read_file(&source_settings).unwrap();
        assert!(
            source_after
                .instances
                .iter()
                .all(|instance| instance.name != "LinkedScript")
        );
        let target_after = SettingsBytecode::read_file(&target_settings).unwrap();
        let moved = target_after
            .instances
            .iter()
            .find(|instance| instance.name == "LinkedScript")
            .unwrap();
        assert_eq!(moved.class_name, "ModuleScript");
        assert_eq!(moved.properties.get("Source"), Some(&json!("return 42")));

        let _ = fs::remove_dir_all(project_root);
    }

    fn assert_ref_index(value: Option<&Value>, expected_one_based_index: usize) {
        let object = value
            .and_then(Value::as_object)
            .expect("expected Ref object");
        assert_eq!(object.get("_type").and_then(Value::as_str), Some("Ref"));
        assert_eq!(
            object.get("instanceIndex").and_then(Value::as_u64),
            Some(expected_one_based_index as u64)
        );
    }

