    #[test]
    fn link_pack_inlines_source_and_removes_disk_mirrors() {
        let dir = link_test_dir("link-pack-cleanup");
        let src_root = dir.join("src");
        let service_dir = src_root.join("ReplicatedStorage");
        fs::create_dir_all(service_dir.join("Pkg")).unwrap();
        let settings_path = service_dir.join("__roblox_sync_settings.rbsync");
        SettingsBytecode {
            version: SETTINGS_BINARY_VERSION,
            instances: vec![
                SettingsBytecodeInstance {
                    settings_id: "root".into(),
                    name: "ReplicatedStorage".into(),
                    class_name: "ReplicatedStorage".into(),
                    parent_index: None,
                    properties: Map::new(),
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "pkg".into(),
                    name: "Pkg".into(),
                    class_name: "Folder".into(),
                    parent_index: Some(0),
                    properties: Map::new(),
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "script".into(),
                    name: "Child".into(),
                    class_name: "Script".into(),
                    parent_index: Some(1),
                    properties: Map::from_iter([(
                        "Source".to_string(),
                        Value::String("__SOURCE_EXTERNAL__".to_string()),
                    )]),
                    attributes: Map::new(),
                },
            ],
        }
        .write_file(&settings_path)
        .unwrap();
        let source_path = service_dir.join("Pkg").join("Child.server.luau");
        fs::write(&source_path, "print('packed')").unwrap();

        link_pack(LinkPackArgs {
            project_root: dir.clone(),
            src_root: PathBuf::from("src"),
            manifest: PathBuf::from("renium-link.json"),
            link_folder: Some(PathBuf::from("links")),
            id: None,
            service: "ReplicatedStorage".into(),
            path_segments_json: r#"["ReplicatedStorage","Pkg"]"#.into(),
            writable: false,
            pretty: false,
        })
        .unwrap();

        assert!(!source_path.exists());
        assert!(!service_dir.join("Pkg").exists());

        let canonical_settings_path = service_settings_path(&service_dir);
        assert!(!settings_path.exists());
        let updated = SettingsBytecode::read_file(&canonical_settings_path).unwrap();
        let script = updated
            .instances
            .iter()
            .find(|instance| instance.settings_id == "script")
            .unwrap();
        assert_eq!(
            script.properties.get("Source"),
            Some(&json!("print('packed')"))
        );

        let package = SettingsBytecode::read_file(&dir.join("links").join("pkg.renium")).unwrap();
        let packaged_script = package
            .instances
            .iter()
            .find(|instance| instance.name == "Child")
            .unwrap();
        assert_eq!(
            packaged_script.properties.get("Source"),
            Some(&json!("print('packed')"))
        );

        fs::remove_dir_all(dir).unwrap();
    }

