    #[test]
    fn bytecode_remove_instance_removes_source_files_and_empty_dirs() {
        let dir = link_test_dir("remove-source-files");
        let service_dir = dir.join("src").join("ReplicatedStorage");
        fs::create_dir_all(&service_dir).unwrap();
        let settings_path = service_dir.join("__roblox_sync_settings.rbsync");
        let document = SettingsBytecode {
            version: SETTINGS_BINARY_VERSION,
            instances: vec![
                SettingsBytecodeInstance {
                    settings_id: "root".to_string(),
                    name: "ReplicatedStorage".to_string(),
                    class_name: "ReplicatedStorage".to_string(),
                    parent_index: None,
                    properties: Map::new(),
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "pkg".to_string(),
                    name: "Pkg".to_string(),
                    class_name: "Folder".to_string(),
                    parent_index: Some(0),
                    properties: Map::new(),
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "script".to_string(),
                    name: "Child".to_string(),
                    class_name: "Script".to_string(),
                    parent_index: Some(1),
                    properties: Map::new(),
                    attributes: Map::new(),
                },
            ],
        };
        document.write_file(&settings_path).unwrap();
        let source_paths =
            build_editor_source_paths_by_index(&document, "ReplicatedStorage", &service_dir);
        let source_path = source_paths[2].as_ref().unwrap();
        fs::create_dir_all(source_path.parent().unwrap()).unwrap();
        fs::write(source_path, "print('delete me')").unwrap();
        assert!(source_path.exists());

        bytecode_remove_instance(BytecodeRemoveInstanceArgs {
            service_or_file: None,
            settings_file: Some(settings_path.clone()),
            settings_id: Some("pkg".into()),
            index: None,
            name: None,
            class_name: None,
            no_recursive: false,
            pretty: false,
        })
        .unwrap();

        assert!(!source_path.exists());
        assert!(!service_dir.join("Pkg").exists());
        let canonical_settings_path = service_settings_path(&service_dir);
        assert!(!settings_path.exists());
        let updated = SettingsBytecode::read_file(&canonical_settings_path).unwrap();
        assert_eq!(updated.instances.len(), 1);
        fs::remove_dir_all(dir).unwrap();
    }

