    #[test]
    fn link_manifest_rejects_duplicate_ids() {
        let root = link_test_dir("manifest-duplicate-id");
        let path = root.join("renium-link.json");
        fs::write(
            &path,
            r#"{
                "version": 1,
                "links": [
                    {"id":"dup","readOnly":true,"source":{"type":"local","path":"links/a.rbsync"},"targets":[{"service":"ReplicatedStorage","path":["ReplicatedStorage","A"],"ords":[]}]},
                    {"id":"dup","readOnly":true,"source":{"type":"local","path":"links/b.rbsync"},"targets":[{"service":"ReplicatedStorage","path":["ReplicatedStorage","B"],"ords":[]}]}
                ],
                "broken": []
            }"#,
        )
        .unwrap();

        let error = format!("{:#}", read_link_manifest(&path).unwrap_err());
        assert!(error.contains("duplicate renium-link id"));
        let _ = fs::remove_dir_all(&root);
    }

