        fs::create_dir_all(dir.join("links")).unwrap();
        let package_path = dir.join("links").join("pkg.rbsync");
        SettingsBytecode {
            version: SETTINGS_BINARY_VERSION,
            instances: vec![SettingsBytecodeInstance {
                settings_id: "pkg:0".into(),
                name: "Pkg".into(),
                class_name: "Folder".into(),
                parent_index: None,
                properties: Map::new(),
                attributes: Map::new(),
            }],
        }
        .write_file(&package_path)
        .unwrap();
        write_link_manifest(
            &dir.join("renium-link.json"),
            &LinkManifest {
                version: LINK_MANIFEST_VERSION,
                cache_dir: None,
                links: vec![LinkEntry {
                    id: "pkg".into(),
                    read_only: true,
                    source: LinkSource::Local {
                        path: "links/pkg.rbsync".into(),
                    },
                    targets: vec![LinkTargetRef {
                        service: "ReplicatedStorage".into(),
                        path: vec!["ReplicatedStorage".into(), "Pkg".into()],
                        ords: Vec::new(),
                    }],
                }],
                broken: Vec::new(),
            },
        )
        .unwrap();

        let apply_args = || LinkApplyArgs {
            project_root: dir.clone(),
            src_root: PathBuf::from("src"),
            manifest: PathBuf::from("renium-link.json"),
            link: None,
            check: false,
            force_targets: false,
            force_target: Vec::new(),
            offline: true,
            strict: false,
            git_path: "git".into(),
            wally_path: "wally".into(),
            cache_dir: None,
            pretty: false,
        };
        link_apply(apply_args()).unwrap();

        let settings_path = service_settings_path(&service_dir);
        let mut document = SettingsBytecode::read_file(&settings_path).unwrap();
        let package_root =
            resolve_editor_instance_by_path(&document, "ReplicatedStorage", &["Pkg".to_string()])
                .unwrap();
        document.instances.push(SettingsBytecodeInstance {
            settings_id: "editor:injected".into(),
            name: "Injected".into(),
            class_name: "Folder".into(),
            parent_index: Some(package_root),
            properties: Map::new(),
            attributes: Map::new(),
        });
